
let s=JSON.parse(localStorage.getItem('morton-game-v1')||'null')||{lang:'en',clues:[],card:false,pick:false,unlocked:false,setlist:false,solved:false};s.lang='en';const $=x=>document.getElementById(x),t=(a,b)=>s.lang==='zh'?a:b;function save(){localStorage.setItem('morton-game-v1',JSON.stringify(s));render()}function add(id){if(!s.clues.includes(id))s.clues.push(id);save()}const evidence={departure:['Morton：18:30 離開，之後沒用電腦。','Morton: left at 18:30; never touched the laptop afterward.'],edit:['歌單在 18:42 被修改。','Setlist edited at 18:42.'],rehearsal:['排練筆記：First Light → Static → Blue Hour。','Rehearsal notes: First Light → Static → Blue Hour.'],print:['18:41 列印第二頁，Alex 簽名；頁碼及記號吻合。','Page 2 printed at 18:41, signed by Alex; page number and markings match.'],delivery:['轉接器在 18:10 已由 Jamie 簽收。','Adapter signed for by Jamie at 18:10.'],entry:['Casey 使用工作證 R-17：18:39 入場，18:47 離開。','Pass R-17 used by Casey: entered 18:39, left 18:47.'],claim:['Casey 聲稱 18:40 送轉接器，沒碰電腦。','Casey claims to have delivered the adapter at 18:40 without using the laptop.'],video:['18:44 監控：黑色衣袖、橙色腕帶的手藏起撥片、拿起密碼鎖；未拍到臉。','18:44 recording: a hand with a black sleeve and orange wristband hides the pick and picks up the lock; no face is visible.'],photo:['18:25 照片：撥片在桌上，旁邊有閃電標籤用品袋。','18:25 photo: pick on desk beside gear bag with lightning patch.'],locked:['吉他盒被加鎖，紙條：「照今晚的順序」。','Guitar case locked. Note: “In tonight’s order.”']};function btn(a,b,f){let e=document.createElement('button');e.textContent=t(a,b);e.onclick=f;return e}function show(a,b){$('title').textContent=t(a,b);$('content').replaceChildren();if(!$('modal').open)$('modal').showModal()}function p(a,b){let e=document.createElement('p');e.textContent=t(a,b);$('content').append(e)}function action(a,b,f){$('content').append(btn(a,b,f))}function clue(id,a,b){p(a,b);action('加入筆記','Save clue',()=>{add(id);p('已保存。','Saved.');})}function render(){document.documentElement.lang=s.lang==='zh'?'zh-Hant':'en';$('lang').textContent=t('English','繁體中文');$('phone').textContent=t('手機 ●','Phone ●');$('notes').textContent=t('調查筆記','Notebook');$('hint').textContent=t('提示','Hint');$('reset').textContent=t('重新開始','Restart');$('fiction').textContent=t('粉絲創作 · 人物對話與事件均為虛構','Fan-made · Fictional dialogue and events');$('status').textContent=t('物品：','Inventory: ')+[s.card?t('曲目卡','Song cards'):null,s.pick?t('撥片','Pick'):null,s.unlocked?t('吉他','Guitar'):null].filter(Boolean).join(' / ');document.querySelectorAll('[data-obj]').forEach(e=>e.setAttribute('aria-label',t({desk:'電腦與樂譜',case:'吉他盒',coat:'外套',bag:'用品袋',door:'後台門',morton:'Morton'}[e.dataset.obj],e.dataset.obj)))}
function desk(){show('工作電腦','Work laptop');action('檔案','Files',files);action('工作訊息','Work chat',()=>{show('工作訊息','Work chat');p('Jamie 17:20：燈光測試會用另一個順序。正式演出照排練筆記。','Jamie 17:20: lighting test uses a different order. use rehearsal notes for the show.');action('排練筆記','Rehearsal notes',()=>{show('排練筆記','Rehearsal notes');clue('rehearsal','Blue Hour 放最後。First Light 之後直接接 Static。','Blue Hour goes last. Static comes right after First Light.');})});action('列印記錄與紙本','Print log & sheet music',()=>{show('樂譜','Sheet music');clue('print',...evidence.print)});}
function surveillanceClip(){setMode('pc-ui');show('18:44 · 後台監控','18:44 · Backstage recording');p('片段文字還原：黑色衣袖、橙色腕帶的手把撥片放進用品袋，再拿起密碼鎖。鏡頭沒有拍到臉。','Clip transcript: a hand with a black sleeve and orange wristband hides the pick and picks up the lock. No face is visible.');action(s.clues.includes('video')?'✓ 監控證據已保存':'保存監控證據',s.clues.includes('video')?'✓ Recording evidence saved':'Save recording evidence',()=>{add('video');surveillanceClip()});if(s.clues.includes('video'))p('已加入調查筆記，可用於事件還原與人物調查。','Saved to Notebook for reconstruction and investigation.');action('← 返回檔案','← Back to files',files);}
function files(){show('檔案','Files');action('setlist_final.txt', 'setlist_final.txt',()=>{show('setlist_final.txt','setlist_final.txt');p('Static\nBlue Hour\nFirst Light','Static\nBlue Hour\nFirst Light');clue('edit',...evidence.edit);action('還原演出順序','Restore show order',order)});action('setlist_draft.txt','setlist_draft.txt',()=>{show('草稿','Draft');p('First Light\nStatic\n（第三首待定）','First Light\nStatic\n(third song TBD)')});action('器材交收表','Delivery log',()=>{show('器材交收表','Delivery log');clue('delivery',...evidence.delivery)});action('影片資料夾','Recordings',()=>{show('Recordings','Recordings');if(s.clues.includes('edit')&&s.clues.includes('entry')){action('播放 18:44 片段','Play 18:44 clip',surveillanceClip)}else p('檔案索引太多。先找出可疑的時間範圍與入場記錄。','Too many entries. Find the suspicious time window and access record first.');})}
function order(){show('整理歌單','Restore setlist');const names=['First Light','Static','Blue Hour'];let selects=[];for(let i=0;i<3;i++){let e=document.createElement('select');e.innerHTML='<option value="">—</option>'+names.map(n=>'<option>'+n+'</option>').join('');e.setAttribute('aria-label',t('第 '+(i+1)+' 首','Song '+(i+1)));$('content').append(e);selects.push(e)}action('確認','Confirm',()=>{if(selects.map(e=>e.value).join('|')===names.join('|')){s.setlist=true;save();p('已儲存正確歌單。','Correct setlist saved.')}else p('與排練筆記不符，再核對一下。','Doesn’t match the rehearsal notes. Check again.');})}
function phone(){show('手機','Phone');action('Morton','Morton',()=>{show('Morton','Morton');p('我先去試音。幫我看看電腦上的歌單？剛才看起來怪怪的。','heading to soundcheck rn. can you check the setlist? looked kinda off');if(s.clues.includes('edit'))action('詢問 18:42 修改記錄','Ask about the 18:42 edit',()=>{clue('departure','不是我，我 18:30 就去試音了，之後沒碰電腦。','nope, I left for soundcheck at 18:30. haven’t touched the laptop since')});if(s.clues.includes('locked'))action('告訴他吉他盒被鎖','Tell him about the lock',()=>p('等等，什麼？我離開時沒有鎖啊 😭','wait what?? that wasn’t there when I left 😭'));if(s.pick)action('告訴他找到撥片','Tell him you found the pick',()=>p('救星啊。怎麼會跑到那裡 lol','lifesaver. how did it even end up there lol'))});action('工作群聊','Crew chat',()=>{show('工作群聊','Crew chat');p('Alex：樂譜第二頁印得太淡，我拿去補印了。\nJamie：用品袋收在沙發旁邊。','Alex: page 2 was too faint. took it to reprint.\nJamie: gear bag is beside the sofa.');clue('photo',...evidence.photo)});if(s.clues.includes('edit')){action('詢問 Jamie','Ask Jamie',()=>{show('Jamie','Jamie');p('我 18:35 去音控台了。有人說來送器材。工作證叫 Casey，你可以查門口記錄。','headed to the sound desk at 18:35. someone came to drop off gear. pass said Casey. check the door log.');});action('詢問 Casey','Ask Casey',()=>{show('Casey','Casey');clue('claim',...evidence.claim);if(s.clues.includes('delivery'))action('出示交收表','Attach delivery log',()=>p('可能我記錯了，是其他東西吧。','might’ve mixed it up. probably something else'));})}}
function notebook(){show('調查筆記','Notebook');s.clues.forEach(id=>{let e=document.createElement('div');e.className='entry';e.textContent=t(...evidence[id]);$('content').append(e)});if(!s.clues.length)p('在閱讀線索時按「加入筆記」。','Use “Save clue” while examining evidence.');action('時間線','Timeline',()=>{show('時間線','Timeline');['delivery','departure','entry','print','edit','video'].filter(id=>s.clues.includes(id)).forEach(id=>p(...evidence[id]));});action('還原事件','Reconstruction',solve)}
function solve(){show('還原事件','Reconstruction');p('誰搗亂？選擇支持證據。樂譜缺頁也需要合理解釋。','Who interfered? Choose supporting evidence. Explain the missing sheet too.');let who=document.createElement('select');who.innerHTML=['—','Alex','Jamie','Casey'].map(x=>'<option>'+x+'</option>').join('');$('content').append(who);let checks=[];s.clues.forEach(id=>{let label=document.createElement('label'),e=document.createElement('input');e.type='checkbox';e.style.width='auto';e.value=id;label.append(e,document.createTextNode(t(...evidence[id])));label.style.display='block';$('content').append(label);checks.push(e)});action('提交推論','Submit',()=>{let ids=checks.filter(e=>e.checked).map(e=>e.value);if(who.value==='Casey'&&['claim','delivery','video','print'].every(id=>ids.includes(id))){s.solved=true;save();p('確認：Casey 的交收說法與記錄矛盾，錄影片段確認搗亂；Alex 補印樂譜的記錄吻合。','Confirmed: Casey’s delivery claim contradicts the log, and the recording confirms interference. Alex’s reprint record explains the missing sheet.')}else p('證據仍不足。核對說法、交收表、錄影片段，以及補印記錄。','Need more support. Compare the claim, delivery log, recording and reprint record.');})}
document.querySelectorAll('[data-obj]').forEach(e=>e.onclick=()=>{let o=e.dataset.obj;if(o==='desk')desk();if(o==='morton'){show('Morton','Morton');p('先確認歌單，再看看吉他盒。需要的話可以用手機聯絡大家。','check the setlist first, then the guitar case. you can message the crew if you need to')};if(o==='coat'){show('外套口袋','Jacket pocket');p('口袋裡有三張曲目卡：First Light — 4；Static — 7；Blue Hour — 2。','Three song cards: First Light — 4; Static — 7; Blue Hour — 2.');action('拿起曲目卡','Take cards',()=>{s.card=true;save();p('已收取。','Collected.')})};if(o==='case'){show('吉他盒','Guitar case');if(s.unlocked){p('盒子已打開，吉他安全無損。','Case open. The guitar is safe.');clue('locked',...evidence.locked);}else{clue('locked',...evidence.locked);let input=document.createElement('input');input.placeholder=t('三位數密碼','3-digit code');input.setAttribute('aria-label',input.placeholder);input.inputMode='numeric';input.maxLength=3;$('content').append(input);action('開鎖','Unlock',()=>{if(input.value==='472'){s.unlocked=true;add('locked');p('喀。盒子打開了，裡面有吉他和空撥片套。','Click. Inside: the guitar and an empty pick sleeve.')}else p('鎖沒有打開。','Still locked.')})}};if(o==='bag'){show('用品袋','Gear bag');action('查看主袋','Main compartment',()=>p('只有線材與備用電池。','Cables and spare batteries.'));action('打開側袋','Open side pocket',()=>{p('夾層裡有一片橙色撥片。','An orange guitar pick sits in the lining.');action('拿起撥片','Take pick',()=>{s.pick=true;save();p('已收取。','Collected.')})})};if(o==='door'){show('後台門','Backstage door');clue('entry',...evidence.entry);action('前往舞台','Go to stage',()=>{if(s.setlist&&s.unlocked&&s.pick&&s.sheet&&s.solved){s.stageComplete=true;save();show('演出準備完成','Ready for the show');action('返回章節選單','Back to chapters',()=>{openMenu();menuPage='chapters';drawMenu()});p('Morton接過撥片，背上吉他。\n「好，走吧。」\n舞台燈亮起。\n\n案件完成。你可以關閉視窗返回後台。','Morton takes the pick and straps on his guitar.\n“alright, we’re good to go. let’s do this.”\nThe stage lights come on.\n\nCase complete. Close this window to return backstage.')}else p('先恢復歌單、打開吉他盒、找回撥片，整理樂譜，並完成事件還原。','Restore the setlist, unlock the case, recover the pick arrange the sheet music and complete the reconstruction first.')})}});
$('close').onclick=()=>$('modal').close();$('phone').onclick=phone;$('notes').onclick=notebook;$('lang').onclick=()=>{s.lang=s.lang==='zh'?'en':'zh';$('modal').close();save()};$('reset').onclick=()=>{if(confirm(t('清除進度並重新開始？','Clear progress and restart?'))){localStorage.removeItem('morton-game-v1');location.reload()}};$('hint').onclick=()=>{show('提示','Hint');p(!s.setlist?t('在電腦工作訊息裡找排練筆記，核對歌曲順序。','Find rehearsal notes in Work chat to restore the song order.'):!s.unlocked?t('外套口袋的曲目卡，按正式歌單排列數字。','Order the numbers on the jacket’s song cards by the setlist.'):!s.pick?t('用品袋不只一個夾層。','The gear bag has more than one compartment.'):t('保存 Casey 的說法、交收表、入場記錄、錄影片段與列印記錄，再到筆記還原事件。','Save Casey’s claim, delivery log, entry record, recording and print log; reconstruct in Notebook.'))};// Chapter expansion: all extra content has matching localizations.
if(s.version!==2){s.version=2;s.solved=false;s.pick=false;s.clues=s.clues.filter(id=>id!=='video');save()}
evidence.video=['18:44 片段只拍到黑袖口與橙色腕帶，伸手藏起撥片；臉不在畫面中。','18:44 clip shows a black sleeve and orange wristband hiding the pick. The face is out of frame.'];
evidence.pass=['工作證 R-17 屬於 Robin，他說 18:20 借給 Casey；Casey 戴橙色腕帶。','Pass R-17 belongs to Robin, who lent it to Casey at 18:20. Casey wore an orange wristband.'];
evidence.wrist=['器材區合照：Casey 戴橙色腕帶、穿黑長袖；Alex 穿灰短袖，Jamie 戴藍腕帶。','Crew photo: Casey wears black sleeves and an orange wristband; Alex wears grey short sleeves; Jamie wears blue.'];
evidence.pickdetail=['Morton常用素面橙色三角撥片，正反面都沒有圖案。','Morton uses a orange triangular pick with a small white star on the back.'];
evidence.sheet=['樂譜順序 A → C → B；A 結尾 8 接 C 開頭 9，C 結尾 16 接 B 開頭 17。','Sheet order A → C → B: A ends at bar 8, C starts at 9 and ends at 16, B starts at 17.'];
const baseDesk=desk,baseFiles=files,basePhone=phone,baseSolve=solve;
desk=function(){if(s.login){baseDesk();action('郵件','Mail',mail);action('回收桶','Trash',trash);return}show('電腦登入','Laptop login');p('帳號：CREW\n提示：工作證編號，不要連字號。\n桌上的工作證可查看。','Account: CREW\nHint: crew pass ID, without the hyphen.\nInspect the pass on the desk.');action('查看桌上工作證','Inspect desk pass',()=>p('後台助手 / 工作證 B-204','Backstage assistant / Pass B-204'));let e=document.createElement('input');e.placeholder=t('登入密碼','Password');$('content').append(e);action('登入','Log in',()=>{if(e.value.trim().toUpperCase()==='B204'){s.login=true;save();desk()}else p('密碼不符，請核對工作證。','Incorrect. Check the pass.');});};
function mail(){show('郵件','Mail');action('Robin：工作證借用','Robin: borrowed pass',()=>clue('pass',...evidence.pass));action('Jamie：器材區合照','Jamie: crew photo',()=>clue('wrist',...evidence.wrist));action('排練：樂譜接續','Rehearsal: sheet continuity',()=>p('重新列印後頁碼有遺漏，用小節接續核對：每段結尾的下一個數字，應是下一頁的起點。','Page numbers disappeared on reprint. Match bar numbers: the next page begins one bar after the previous ends.'));action('演出後：感謝','After the show: thanks',()=>p(s.solved?'調查完成後的小彩蛋：Thanks for having my back 🐾':'演出後才會收到這封信。',s.solved?'A little bonus: Thanks for having my back 🐾':'This message arrives after the case is solved.'));}
function trash(){show('回收桶','Trash');action('lighting_test_old.txt','lighting_test_old.txt',()=>p('Static → Blue Hour → First Light\n註：只供燈光測試，別覆蓋正式版本。','Static → Blue Hour → First Light\nLighting test only. Don’t overwrite the show version.'));action('dog_sticker.png','dog_sticker.png',()=>{s.bonus=true;save();p('找到小狗貼紙彩蛋 🐾','Found a little dog sticker bonus 🐾')});}
files=function(){baseFiles();action('rehearsal_notes.txt','rehearsal_notes.txt',()=>{show('排練筆記','Rehearsal notes');clue('rehearsal','Blue Hour 放最後；First Light 後接 Static。','Blue Hour goes last; Static follows First Light.')});};
phone=function(){basePhone();action('詢問 Robin 的工作證','Ask Robin about the pass',()=>{show('Robin','Robin');if(s.clues.includes('entry'))clue('pass',...evidence.pass);else p('先確認進入後台的工作證編號。','Check the backstage entry record first.');});action('詢問撥片特徵','Ask about the pick',()=>{show('Morton','Morton');clue('pickdetail','橙色那片，背面有小星星。白色的是備用的 btw','the orange one with a little star on the back. white one’s a spare btw');});};
const bagHot=document.querySelector('[data-obj="bag"]');bagHot.onclick=()=>{show('用品袋','Gear bag');action('主袋：白色撥片','Main pocket: white pick',()=>p('一片白色圓角撥片，不確定是不是要找的那片。','White rounded pick. Is this the one you need?'));action('側袋：橙色撥片','Side pocket: orange pick',()=>{p('橙色三角撥片。可以翻到背面查看。','Orange triangular pick. Turn it over to inspect.');action('翻面','Turn over',()=>{p('背面有一顆白色小星星。','A small white star on the back.');action('確認並收取','Identify and collect',()=>{if(s.clues.includes('pickdetail')){s.pick=true;save();p('已確認是他要的撥片。','Confirmed: this is his pick.')}else p('先用手機問清楚他要哪片。','Ask him which pick he needs first.');});});});action('內層：藍色撥片','Lining: blue pick',()=>p('藍色撥片上印著器材租借公司的名字。','Blue pick with a rental company name.'));};
const sheetButton=document.createElement('button');sheetButton.className='hot';sheetButton.style.cssText='left:17%;top:27%;width:10%;height:7%';sheetButton.setAttribute('aria-label',t('整理樂譜','Arrange sheet music'));document.querySelector('.room').append(sheetButton);sheetButton.onclick=()=>{show('整理樂譜','Arrange sheet music');p('A：小節 1–8\nB：小節 17–24\nC：小節 9–16（補印頁，Alex 簽名）\n依小節接續排好三頁。','A: bars 1–8\nB: bars 17–24\nC: bars 9–16 (reprint signed by Alex)\nArrange the three pages by bar continuity.');let e=document.createElement('input');e.placeholder='ABC';e.maxLength=3;$('content').append(e);action('確認順序','Check order',()=>{if(e.value.toUpperCase()==='ACB'){s.sheet=true;add('sheet');p('樂譜整理完成。補印頁記號也與原稿一致。','Sheet music restored. Reprint markings match the original.')}else p('檢查每頁的小節起點與終點。','Check the first and last bar of each page.');});};
solve=function(){show('還原事件','Reconstruction');p('影片沒有拍到臉。誰符合腕帶與衣袖特徵，並使用了借來的工作證？請附上證據。','No face appears in the clip. Who matches the wristband and sleeve, and used the borrowed pass? Attach evidence.');let who=document.createElement('select');who.innerHTML=['—','Alex','Jamie','Casey'].map(x=>'<option>'+x+'</option>').join('');$('content').append(who);let checks=[];s.clues.forEach(id=>{let label=document.createElement('label'),e=document.createElement('input');e.type='checkbox';e.style.width='auto';e.value=id;label.append(e,document.createTextNode(t(...evidence[id])));label.style.display='block';$('content').append(label);checks.push(e)});action('提交推論','Submit',()=>{const ids=checks.filter(e=>e.checked).map(e=>e.value);if(who.value==='Casey'&&['claim','delivery','entry','pass','wrist','video','print'].every(id=>ids.includes(id))){s.solved=true;save();p('確認：交收說法矛盾；借證與入場記錄吻合；影片衣袖及腕帶與合照一致。樂譜只是 Alex 拿去補印。','Confirmed: delivery contradiction; borrowed pass matches entry; sleeve and wristband match the crew photo. Alex only took the sheet to reprint.')}else p('仍有缺口。需要交收矛盾、入場與借證、影片與合照，以及補印記錄。','Missing support: delivery contradiction, entry and borrowed pass, recording and crew photo, plus the reprint log.');});};
const originalHint=$('hint').onclick;$('hint').onclick=()=>{if(!s.login){show('提示','Hint');p('登入提示在桌上工作證，去掉連字號。','Inspect the desk pass. Remove the hyphen.')}else if(!s.sheet&&s.setlist&&s.unlocked&&s.pick){show('提示','Hint');p('點桌上樂譜，依小節數接續。','Click the sheet music. Match consecutive bar numbers.')}else{originalHint();if(s.pick)p('郵件裡還有借證記錄和器材區合照。','Mail contains the borrowed-pass record and crew photo.')}};

function mortonChat(){show('Morton · 訊息','Morton · Messages');action('← 返回聯絡人','← Contacts',phone);p('我先去試音，幫我確認一下歌單？','heading to soundcheck rn. can you check the setlist?');action('詢問撥片特徵','Ask about the pick',()=>{clue('pickdetail','橙色那片，背面有小星星。白色的是備用的 btw','the orange one with a little star on the back. white one’s a spare btw');});action('詢問歌單修改時間','Ask about the setlist edit',()=>{if(s.clues.includes('edit'))clue('departure','不是我，我 18:30 就去試音了，之後沒碰電腦。','nope, I left for soundcheck at 18:30. haven’t touched the laptop since');else p('先到電腦查看歌單的修改記錄，並加入筆記。','Check the setlist’s edit record on the laptop and save it first.');});if(s.clues.includes('locked'))action('詢問吉他盒的鎖','Ask about the lock',()=>p('我離開時沒有鎖啊 😭','that wasn’t there when I left 😭'));if(s.pick)action('告訴他找到撥片','Tell him you found the pick',()=>p('救星啊！','lifesaver!'));}
const expandedPhone=phone;phone=function(){expandedPhone();const first=$('content').querySelector('button');if(first)first.onclick=mortonChat;};
$('phone').onclick=phone;
document.querySelector('[data-obj="morton"]').onclick=mortonChat;

// Separate event reconstruction from identification.
const cases=[
{id:'setlist',title:['歌單順序被改','Setlist changed'],question:['歌單發生了什麼？','What happened to the setlist?'],options:[['有人在試音開始後改動正式歌單','Someone edited the show setlist after soundcheck began'],['Morton在離開前自行調整','Morton changed it before leaving'],['只有檔案名稱變動，順序沒變','Only the filename changed']],answer:0,required:['edit','departure','rehearsal'],explain:['修改時間晚於Morton離開時間，且內容與排練筆記不符。','The edit came after Morton left, and the order contradicts the rehearsal notes.']},
{id:'music',title:['樂譜缺頁','Missing sheet'],question:['第二頁為什麼不在桌上？','Why was page 2 missing?'],options:[['搗亂者銷毀了第二頁','The intruder destroyed page 2'],['Alex 拿去補印，並未惡意修改','Alex took it to reprint, without malicious changes'],['原本就沒有第二頁','There was never a page 2']],answer:1,required:['print','sheet'],explain:['列印記錄、Alex 簽名，以及小節接續都吻合。','The print log, Alex’s signature and bar continuity agree.']},
{id:'lock',title:['吉他盒被鎖','Locked guitar case'],question:['這把鎖是怎麼來的？','Where did the lock come from?'],options:[['原本就有，Morton忘了','It was always there; Morton forgot'],['吉他盒原廠自動上鎖','The case locked itself'],['有人帶來密碼鎖，故意阻礙取吉他','Someone brought a lock to block access to the guitar']],answer:2,required:['locked','video'],explain:['盒上留有挑釁紙條；片段中的手拿起了同樣的鎖。','The case has a taunting note; the recording shows a hand picking up the matching lock.']},
{id:'pick',title:['撥片失蹤','Missing pick'],question:['撥片怎麼進了用品袋？','How did the pick end up in the bag?'],options:[['有人從桌上拿走，藏進袋內','Someone took it from the desk and hid it in the bag'],['它一直是器材公司的用品','It always belonged to the rental company'],['它從吉他盒裡自己掉進袋子','It fell from the case into the bag']],answer:0,required:['photo','video','pickdetail'],explain:['早先照片顯示撥片在桌上；片段顯示藏入袋中的動作，正反面無圖案的特徵也吻合。','The earlier photo places it on the desk; the clip shows it being hidden, and the unmarked surfaces match.']}
];
if(!s.finalFlow){s.finalFlow=true;s.solved=false;s.reconstructed=[];save()}s.reconstructed=s.reconstructed||[];
function backNotes(){action('← 返回調查筆記','← Notebook',notebook)}
function reconstruction(){show('事件還原','Event reconstruction');backNotes();p('逐件判斷發生了什麼，並選擇支持證據。四件事都還原後，再確認搗亂者。','Explain each event and attach supporting clues. Reconstruct all four before identifying the intruder.');cases.forEach(c=>{let e=document.createElement('div');e.className='entry';e.append(btn((s.reconstructed.includes(c.id)?'✓ ':'○ ')+c.title[0],(s.reconstructed.includes(c.id)?'✓ ':'○ ')+c.title[1],()=>eventForm(c)));$('content').append(e)});if(cases.every(c=>s.reconstructed.includes(c.id)))action('前往確認搗亂者 →','Identify the intruder →',identify);}
function eventForm(c){show(...c.title);action('← 返回事件列表','← Events',reconstruction);if(s.reconstructed.includes(c.id)){p('✓ 已還原','✓ Reconstructed');p(...c.explain);return}p(...c.question);let answer=document.createElement('select');answer.innerHTML='<option value="">'+t('選擇推論','Choose an explanation')+'</option>'+c.options.map((o,i)=>'<option value="'+i+'">'+t(...o)+'</option>').join('');answer.setAttribute('aria-label',t('事件解釋','Event explanation'));$('content').append(answer);p('選擇證據：','Attach evidence:');const checks=[];s.clues.forEach(id=>{let label=document.createElement('label');label.style.display='block';let e=document.createElement('input');e.type='checkbox';e.style.width='auto';e.value=id;label.append(e,document.createTextNode(t(...evidence[id])));$('content').append(label);checks.push(e)});if(!s.clues.length)p('筆記還沒有線索。請先在閱讀時保存。','No clues saved yet. Save them while investigating.');action('驗證推論','Check explanation',()=>{const ids=checks.filter(e=>e.checked).map(e=>e.value);if(answer.value===''){p('先選擇一個推論。','Choose an explanation first.');return}if(Number(answer.value)!==c.answer){p('這個推論與現場或記錄有矛盾，請重新核對。','This explanation contradicts the scene or records. Check again.');return}const missing=c.required.filter(id=>!ids.includes(id));if(missing.length){p('還需要勾選：\n'+missing.map(id=>t(...evidence[id])+(s.clues.includes(id)?'':'（尚未保存）')).join('\n'),'Also select:\n'+missing.map(id=>t(...evidence[id])+(s.clues.includes(id)?'':' (not saved yet)')).join('\n'));return}if(!s.reconstructed.includes(c.id))s.reconstructed.push(c.id);save();p('✓ 事件還原成功','✓ Event reconstructed');p(...c.explain);action('下一件事件 →','Next event →',reconstruction);});}
function identify(){show('確認搗亂者','Identify the intruder');backNotes();if(!cases.every(c=>s.reconstructed.includes(c.id))){p('先完成四件事的還原，分清哪些是搗亂、哪些是誤會。','Reconstruct all four events first to separate interference from coincidence.');action('打開事件還原','Reconstruct events',reconstruction);return}if(s.solved){p('✓ 已確認 Casey 是搗亂者。演出用品準備好後，點後台門前往舞台。','✓ Casey identified as the intruder. Finish preparing the gear, then use the backstage door.');return}p('影片沒拍到臉。選出人物，並附上能連結身分、入場和動作的證據。','The recording shows no face. Choose a person and connect their identity, access and actions with evidence.');let who=document.createElement('select');who.innerHTML=['—','Alex','Jamie','Casey'].map(x=>'<option>'+x+'</option>').join('');who.setAttribute('aria-label',t('搗亂者','Intruder'));$('content').append(who);const checks=[];s.clues.forEach(id=>{let l=document.createElement('label');l.style.display='block';let e=document.createElement('input');e.type='checkbox';e.style.width='auto';e.value=id;l.append(e,document.createTextNode(t(...evidence[id])));$('content').append(l);checks.push(e)});action('提交調查結論','Submit conclusion',()=>{const ids=checks.filter(e=>e.checked).map(e=>e.value);if(who.value==='—'){p('請先選擇人物。','Choose a person first.');return}if(who.value!=='Casey'){p('現有證據不足以支持這個人物，請比對衣袖、腕帶與工作證。','The evidence does not support this person. Compare sleeves, wristbands and the pass.');return}if(!['claim','delivery','entry','pass','wrist','video'].every(id=>ids.includes(id))){p('身分連結仍有缺口。比對交收說法、借證、入場記錄，以及影片與合照。','The identity link is incomplete. Compare the delivery claim, borrowed pass, entry log, recording and crew photo.');return}s.solved=true;save();p('✓ 調查完成','✓ Investigation complete');p('Casey 借證進入後台；交收理由與簽收時間矛盾；合照中的衣袖與橙色腕帶，對應影片裡藏撥片、拿鎖的人。\n\n歌單、吉他盒與撥片都是搗亂事件，樂譜缺頁則是補印造成的誤會。','Casey entered with a borrowed pass. The delivery story contradicts the signed log. The black sleeve and orange wristband in the crew photo match the hand hiding the pick and taking the lock.\n\nThe setlist, lock and pick were interference; the missing sheet was a reprint mix-up.');action('檢查演出準備 →','Check show readiness →',readiness);});}
function readiness(){show('演出準備','Show readiness');backNotes();[[s.setlist,'歌單已恢復','Setlist restored'],[s.sheet,'樂譜已整理','Sheet music arranged'],[s.unlocked,'吉他盒已打開','Guitar case unlocked'],[s.pick,'撥片已確認','Pick identified'],[s.solved,'搗亂者已確認','Intruder identified']].forEach(([ok,a,b])=>p((ok?'✓ ':'○ ')+a,(ok?'✓ ':'○ ')+b));p('全部完成後，關閉窗口並點後台門。','Once complete, close this window and click the backstage door.');}
notebook=function(){show('調查筆記','Notebook');action('線索收藏','Saved clues',()=>{show('線索收藏','Saved clues');backNotes();if(!s.clues.length)p('在查看內容時按「加入筆記」。','Use “Save clue” while examining content.');s.clues.forEach(id=>p(...evidence[id]));});action('時間線','Timeline',()=>{show('時間線','Timeline');backNotes();['delivery','pass','departure','entry','print','edit','video'].filter(id=>s.clues.includes(id)).forEach(id=>p(...evidence[id]));});action('事件還原（'+s.reconstructed.length+'/4）','Event reconstruction ('+s.reconstructed.length+'/4)',reconstruction);action('確認搗亂者','Identify the intruder',identify);action('演出準備清單','Show checklist',readiness);p(s.solved?'調查已完成。':'收集線索 → 還原四件事 → 確認搗亂者。',s.solved?'Investigation complete.':'Gather clues → reconstruct four events → identify the intruder.');};solve=reconstruction;$('notes').onclick=notebook;
const flowHint=$('hint').onclick;$('hint').onclick=()=>{flowHint();if(s.pick&&!s.solved)p('調查筆記現在有獨立的「事件還原」與「確認搗亂者」入口。','Notebook now has separate Event reconstruction and Identify the intruder entries.');};

evidence.print=['Alex：補印樂譜記錄 — 18:41 列印第二頁，Alex 簽名；手寫記號與原稿吻合。','Alex: sheet reprint record — page 2 printed at 18:41, signed by Alex; handwritten markings match.'];
if(s.reconstructed.includes('music')&&!s.clues.includes('print'))add('print');
const savedClue=clue;clue=function(id,a,b){if(id==='print'){add('print');p(a,b);p('✓ 已保存至調查筆記，可用於「樂譜缺頁」還原。','✓ Saved to Notebook; available for the missing-sheet reconstruction.');}else savedClue(id,a,b);};
function alexChat(){show('Alex · 訊息','Alex · Messages');action('← 返回聯絡人','← Contacts',phone);p('第二頁印得太淡，我拿去補印了。18:41 印完，紙上有我的簽名。','page 2 was too faint so I reprinted it. finished at 18:41 — my signature’s on it.');action('查看並保存補印記錄','View and save reprint record',()=>clue('print',...evidence.print));}
const previousPhone=phone;phone=function(){previousPhone();action('Alex · 詢問樂譜','Alex · Ask about sheet music',alexChat);};$('phone').onclick=phone;
const previousEvent=eventForm;eventForm=function(c){previousEvent(c);if(s.reconstructed.includes(c.id)){p('支持證據：','Supporting evidence:');c.required.filter(id=>s.clues.includes(id)).forEach(id=>p(...evidence[id]));}else if(c.id==='music'&&!s.clues.includes('print')){p('還沒有保存 Alex 的補印記錄。可從手機聯絡 Alex，或查看電腦的列印記錄。','Alex’s reprint record has not been saved. Contact Alex on the phone or inspect the laptop print log.');action('聯絡 Alex','Contact Alex',alexChat);}};

if(s.unlocked&&!s.clues.includes('locked'))add('locked');
let chatComposer=null;let uiMode='';const rawShow=show;show=function(a,b){rawShow(a,b);$('modal').className=uiMode;chatComposer=null;};
function setMode(mode){uiMode=mode;$('modal').className=mode}
function openApp(a,b,f){setMode('pc-ui');f();let nav=document.createElement('div');nav.className='app-nav';nav.append(btn('⌂ 桌面','⌂ Desktop',desk));$('content').prepend(nav);}
function icon(a,b,g,f){let e=btn(a,b,f);e.className='desktop-icon';let glyph=document.createElement('span');glyph.className='glyph';glyph.textContent=g;e.prepend(glyph);return e}
desk=function(){setMode('pc-ui');show('CREW.OS / 後台電腦','CREW.OS / Backstage laptop');if(!s.login){let box=document.createElement('div');box.className='login-panel';let intro=document.createElement('p');intro.textContent=t('CREW 登入\n密碼提示：桌上工作證編號，去掉連字號。','CREW LOGIN\nHint: desk crew pass ID, without the hyphen.');let input=document.createElement('input');input.placeholder=t('密碼','Password');box.append(intro,input,btn('登入','Sign in',()=>{if(input.value.trim().toUpperCase()==='B204'){s.login=true;save();desk()}else{intro.textContent=t('密碼不符。請核對桌上的工作證。','Incorrect. Inspect the desk pass.')}}),btn('查看工作證','Inspect pass',()=>{intro.textContent=t('後台助手 / 工作證 B-204','Backstage assistant / Pass B-204')}));$('content').append(box);return}let grid=document.createElement('div');grid.className='desktop-grid';grid.append(icon('檔案','Files','▰',()=>openApp('檔案','Files',files)),icon('工作訊息','Work chat','▤',workChat),icon('郵件','Mail','✉',()=>openApp('郵件','Mail',mail)),icon('回收桶','Trash','♜',()=>openApp('回收桶','Trash',trash)),icon('列印記錄','Print log','▧',()=>openApp('列印記錄','Print log',()=>{show('列印記錄','Print log');clue('print',...evidence.print)})));$('content').append(grid);let cap=document.createElement('p');cap.className='desktop-caption';cap.textContent=t('後台工作站 · 檔案與記錄可加入調查筆記','Backstage workstation · Save relevant records to Notebook');$('content').append(cap)};
function workChat(){openApp('工作訊息','Work chat',()=>{show('CREW / 工作訊息','CREW / Work chat');bubble('Jamie','17:20 · '+t('燈光測試會用另一個順序，正式演出照排練筆記。','lighting test uses a different order. show follows rehearsal notes.'));action('打開附件：排練筆記','Open attachment: rehearsal notes',()=>openApp('排練筆記','Rehearsal notes',()=>{show('排練筆記','Rehearsal notes');clue('rehearsal','Blue Hour 放最後，First Light 之後接 Static。','Blue Hour goes last; Static follows First Light.')}));});}
function bubble(name,message,mine=false){let e=document.createElement('div');e.className='chat-bubble'+(mine?' mine':'');let n=document.createElement('small');n.textContent=name;let m=document.createElement('div');m.textContent=message;e.append(n,m);if(chatComposer)$('content').insertBefore(e,chatComposer);else $('content').append(e)}
function reply(a,b,responseA,responseB,id){let e=btn(a,b,()=>{bubble(t('你','You'),t(a,b),true);bubble($('title').textContent,t(responseA,responseB));if(id){action('保存這條線索','Save this clue',()=>{add(id);p('✓ 已加入筆記','✓ Saved to Notebook')});}});e.className='reply-option';(chatComposer||$('content')).append(e);}
function contact(name,preview,f){let e=document.createElement('button');e.className='contact';let av=document.createElement('span');av.className='avatar';av.textContent=name[0];let text=document.createElement('span');text.textContent=name+' · '+preview;e.append(av,text);e.onclick=f;$('content').append(e)}
phone=function(){setMode('phone-ui');show('Messages','Messages');p('聯絡人','Contacts');contact('Morton',t('試音中','at soundcheck'),mortonChat);contact('Alex',t('舞台助理','stage crew'),alexChat);contact('Jamie',t('音響助理','sound crew'),jamieChat);contact('Casey',t('臨時人員','temporary crew'),caseyChat);contact('Robin',t('工作證持有人','pass holder'),robinChat);contact(t('工作群聊','Crew chat'),t('照片與通知','photos & updates'),crewChat)};
function chatHead(name){setMode('phone-ui');show(name,name);action('← 聯絡人','← Contacts',phone)}
function composeLabel(){chatComposer=document.createElement('div');chatComposer.className='compose';$('content').append(chatComposer);let p1=document.createElement('p');p1.className='hint';p1.textContent=t('選擇要傳送的訊息','Choose a message to send');chatComposer.append(p1)}
mortonChat=function(){chatHead('Morton');bubble('Morton',t('我先去試音，幫我看一下歌單？','heading to soundcheck rn. can you check the setlist?'));composeLabel();reply('你的撥片長什麼樣？','what does your pick look like?','素面橙色那片，兩面都沒有圖案。有星星的不是我的。','the plain orange one. no markings on either side — the one with a star isn’t mine.','pickdetail');if(s.clues.includes('edit'))reply('歌單 18:42 被修改，是你嗎？','the setlist was edited at 18:42. was that you?','不是，我 18:30 就去試音了，之後沒碰電腦。','nope, left at 18:30. haven’t touched the laptop since','departure');if(s.clues.includes('locked'))reply('你的吉他盒被加鎖了。','someone locked your guitar case.','等等，什麼？我離開時沒有鎖啊 😭','wait what?? that wasn’t there when I left 😭');if(s.pick)reply('撥片找到了！','found your pick!','救星啊！怎麼會跑到袋子裡 lol','lifesaver! how did it end up in the bag lol')};
alexChat=function(){chatHead('Alex');bubble('Alex',t('有什麼需要幫忙嗎？','need a hand?'));composeLabel();reply('桌上的樂譜少了一頁。','there’s a page missing from the sheet music.','第二頁印得太淡，我拿去補印了。18:41 印完，紙上有我的簽名。','page 2 was too faint so I reprinted it. finished at 18:41 — my signature’s on it.','print')};
function jamieChat(){chatHead('Jamie');bubble('Jamie',t('我在音控台。','at the sound desk.'));composeLabel();reply('你何時離開後台？','when did you leave backstage?','18:35。有個拿工作證的人說要送器材，工作證名字是 Casey。可以查門口記錄。','18:35. someone with a pass came to drop off gear — name said Casey. check the door log.');reply('用品袋放在哪裡？','where’s the gear bag?','沙發旁邊，記得看看側袋。','beside the sofa. check the side pocket too.');}
function caseyChat(){chatHead('Casey');bubble('Casey',t('怎麼了？','what’s up?'));composeLabel();reply('你今天來後台做什麼？','what brought you backstage today?','18:40 送轉接器而已，沒用電腦。','just dropped off an adapter at 18:40. didn’t use the laptop.','claim');if(s.clues.includes('delivery'))reply('轉接器 18:10 就簽收了。','the adapter was signed for at 18:10.','可能記錯了，是其他東西吧。','might’ve mixed it up. probably something else.');}
function robinChat(){chatHead('Robin');bubble('Robin',t('我剛回器材區。','just got back to the gear area.'));composeLabel();if(s.clues.includes('entry'))reply('R-17 工作證是你的嗎？','is pass R-17 yours?','是，18:20 借給了 Casey。他今天戴橙色腕帶。','yeah, lent it to Casey at 18:20. he’s wearing an orange wristband today.','pass');else p('找到入場記錄後，可以詢問工作證。','Find the entry log to ask about the pass.');}
function crewChat(){chatHead(t('工作群聊','Crew chat'));bubble('Alex',t('樂譜第二頁拿去補印了。','took page 2 to reprint.'));bubble('Jamie',t('用品袋收在沙發旁。','gear bag’s beside the sofa.'));action('18:25 後台照片','18:25 backstage photo',()=>{bubble('Jamie',t(...evidence.photo));action('保存照片線索','Save photo clue',()=>add('photo'))});action('器材區合照','Crew photo',()=>{bubble('Jamie',t(...evidence.wrist));action('保存合照線索','Save crew-photo clue',()=>add('wrist'))});}
