function pickView(color,back=false){setMode('item-ui');show('撥片','Guitar pick');let item=document.createElement('div');item.className='pick-shape';item.style.background=(color==='orange'||color==='orange-star')?'#ed942e':color==='white'?'#ede9da':'#4b7ba6';item.textContent=back&&color==='orange-star'?'★':'';$('content').append(item);p(back?'背面':'正面',back?'Back':'Front');if(back&&color==='blue')p('印著器材租借公司的名字。','Printed with the rental company’s name.');action('翻面','Flip',()=>pickView(color,!back));action('← 用品袋','← Gear bag',gearBag);action('確認並收取','Identify & collect',()=>{if(!s.clues.includes('pickdetail')){p('先向 Morton 確認撥片的特徵。','Ask Morton about his pick’s details first.');return}if(!back){p('先翻到背面核對，兩面都需要查看。','Flip it over to check the back. Inspect both sides first.');return}if(color!=='orange'){p(color==='orange-star'?'背面有星星，不符合 Morton 說的素面撥片。':'顏色不符合 Morton 說的橙色撥片。',color==='orange-star'?'The star on the back doesn’t match Morton’s plain pick.':'The colour doesn’t match Morton’s orange pick.');return}s.pick=true;save();p('✓ 已確認兩面都沒有圖案，收取素面橙色撥片。','✓ Both sides are unmarked. Plain orange pick collected.');});}
function gearBag(){setMode('item-ui');show('用品袋','Gear bag');p('逐個查看袋內物品。','Inspect each item in the bag.');action('主袋 · 白色撥片','Main pocket · White pick',()=>pickView('white'));action('側袋 · 橙色撥片','Side pocket · Orange pick',()=>pickView('orange'));action('內層 · 另一片橙色撥片','Lining · Another orange pick',()=>pickView('orange-star'));action('底袋 · 藍色撥片','Bottom pocket · Blue pick',()=>pickView('blue'));}
function guitarCase(){setMode('item-ui');show('吉他盒','Guitar case');if(s.unlocked){let img=document.createElement('img');img.src='assets/guitar-red.png';img.alt=t('紅色吉他的像素圖','Pixel art of the red guitar');img.className='guitar-sprite';$('content').append(img);p('吉他安全無損，但撥片套是空的。','The guitar is safe, but the pick sleeve is empty.');clue('locked',...evidence.locked);return}clue('locked',...evidence.locked);let input=document.createElement('input');input.maxLength=3;input.inputMode='numeric';input.placeholder=t('三位數密碼','3-digit code');input.setAttribute('aria-label',input.placeholder);$('content').append(input);action('開鎖','Unlock',()=>{if(input.value==='472'){s.unlocked=true;add('locked');guitarCase()}else p('鎖沒有打開。','Still locked.');});}
