s.chatHistory=s.chatHistory||{};s.sentMessages=s.sentMessages||{};let activeContact='';
function chatHead(name){setMode('phone-ui');show(name,name);activeContact=name;action('← 聯絡人','← Contacts',phone)}
function composeLabel(){(s.chatHistory[activeContact]||[]).forEach(m=>{bubble(t('你','You'),t(...m.question),true);bubble(activeContact,t(...m.answer));if(m.evidence&&!s.clues.includes(m.evidence))action('保存這條線索','Save this clue',()=>{add(m.evidence);p('✓ 已加入筆記','✓ Saved to Notebook')});});chatComposer=document.createElement('div');chatComposer.className='compose';$('content').append(chatComposer);let e=document.createElement('p');e.className='hint';e.textContent=t('新發現會解鎖可傳送的訊息。','New discoveries unlock messages to send.');chatComposer.append(e);}
function reply(a,b,ra,rb,id){const key=activeContact+'|'+b;if(s.sentMessages[key])return;let e=btn(a,b,()=>{bubble(t('你','You'),t(a,b),true);bubble(activeContact,t(ra,rb));s.sentMessages[key]=true;(s.chatHistory[activeContact]||=[]).push({question:[a,b],answer:[ra,rb],evidence:id||null});save();e.remove();if(id)action('保存這條線索','Save this clue',()=>{add(id);p('✓ 已加入筆記','✓ Saved to Notebook')});});e.className='reply-option';(chatComposer||$('content')).append(e);}
