mortonChat=function(){chatHead('Morton');bubble('Morton',t('我先去試音，幫我看一下歌單？','heading to soundcheck rn. can you check the setlist?'));composeLabel();if(s.seenPick||s.pick||s.clues.includes('pickdetail'))reply('你的撥片長什麼樣？','what does your pick look like?','素面橙色那片，兩面都沒有圖案。有星星的不是我的。','the plain orange one. no markings on either side — the one with a star isn’t mine.','pickdetail');if(s.clues.includes('edit'))reply('歌單 18:42 被修改，是你嗎？','the setlist was edited at 18:42. was that you?','不是，我 18:30 就去試音了，之後沒碰電腦。','nope, left at 18:30. haven’t touched the laptop since','departure');if(s.clues.includes('locked'))reply('你的吉他盒被加鎖了。','someone locked your guitar case.','等等，什麼？我離開時沒有鎖啊 😭','wait what?? that wasn’t there when I left 😭');if(s.pick)reply('撥片找到了！','found your pick!','救星啊！怎麼會跑到袋子裡 lol','lifesaver! how did it end up in the bag lol')};
alexChat=function(){chatHead('Alex');bubble('Alex',t('有什麼需要幫忙嗎？','need a hand?'));composeLabel();if(s.seenSheet||s.sheet||s.clues.includes('print'))reply('桌上的樂譜少了一頁。','there’s a page missing from the sheet music.','第二頁印得太淡，我拿去補印了。18:41 印完，紙上有我的簽名。','page 2 was too faint so I reprinted it. finished at 18:41 — my signature’s on it.','print')};
function jamieChat(){chatHead('Jamie');bubble('Jamie',t('我在音控台。','at the sound desk.'));composeLabel();if(s.clues.includes('edit')||s.clues.includes('locked'))reply('你何時離開後台？','when did you leave backstage?','18:35。有個拿工作證的人說要送器材，工作證名字是 Casey。可以查門口記錄。','18:35. someone with a pass came to drop off gear — name said Casey. check the door log.');if(s.clues.includes('photo'))reply('用品袋放在哪裡？','where’s the gear bag?','沙發旁邊，記得看看側袋。','beside the sofa. check the side pocket too.');}
function caseyChat(){chatHead('Casey');bubble('Casey',t('怎麼了？','what’s up?'));composeLabel();if(s.clues.includes('entry'))reply('你今天來後台做什麼？','what brought you backstage today?','18:40 送轉接器而已，沒用電腦。','just dropped off an adapter at 18:40. didn’t use the laptop.','claim');if(s.clues.includes('delivery')&&s.sentMessages['Casey|what brought you backstage today?'])reply('轉接器 18:10 就簽收了。','the adapter was signed for at 18:10.','可能記錯了，是其他東西吧。','might’ve mixed it up. probably something else.');}
