function menuText(tag,a,b,cls){let e=document.createElement(tag);e.textContent=t(a,b);if(cls)e.className=cls;return e}
function drawMenu(){startScreen.replaceChildren();const shell=document.createElement('div');shell.className='menu-shell';const top=document.createElement('div');top.className='menu-top';top.append(menuText('span','MORTON / 像素探索故事','MORTON / PIXEL MYSTERY STORIES','menu-kicker'),btn('English','繁體中文',()=>{s.lang=s.lang==='zh'?'en':'zh';save();drawMenu()}));shell.append(top);if(menuPage==='home'){shell.append(menuText('h1','The Morton Files','The Morton Files'),menuText('p','和Morton 的像素冒險','A pixel adventure with Morton.','menu-description'));let actions=document.createElement('div');actions.className='menu-actions';let chapters=btn('選擇章節','Select chapter',()=>{menuPage='chapters';drawMenu()});chapters.className='menu-primary';actions.append(chapters);if(hasProgress())actions.append(btn(chapterComplete()?'返回第一章':'繼續第一章',chapterComplete()?'Revisit Chapter 1':'Continue Chapter 1',()=>enterChapter(false)));shell.append(actions)}else{shell.append(menuText('h1','章節','CHAPTERS'));let list=document.createElement('div');list.className='chapter-list';let first=document.createElement('article');first.className='chapter-card';first.append(menuText('div','CHAPTER 01 · '+(chapterComplete()?'已完成':hasProgress()?'進行中':'可遊玩'),'CHAPTER 01 · '+(chapterComplete()?'COMPLETE':hasProgress()?'IN PROGRESS':'AVAILABLE'),'chapter-badge'),menuText('h2','後台的不速之客','The Backstage Intruder'),menuText('p','歌單被改、吉他盒被鎖，撥片也不見了。\n在演出開始前，找回用品並還原後台發生的事。','An altered setlist. A locked guitar case. A missing pick.\nRecover the gear and reconstruct what happened backstage.'));let actions=document.createElement('div');actions.className='menu-actions';let begin=btn(hasProgress()?'繼續第一章':'開始第一章',hasProgress()?'Continue Chapter 1':'Start Chapter 1',()=>enterChapter(false));begin.className='menu-primary';actions.append(begin);if(hasProgress())actions.append(btn('重新開始第一章','Restart Chapter 1',()=>enterChapter(true)));first.append(actions,menuText('div','繁體中文 / English · 無倒數 · 自動保存','繁體中文 / English · No timer · Autosave','chapter-note'));let next=document.createElement('article');next.className='chapter-card locked';next.append(menuText('div','CHAPTER 02 · 尚未開放','CHAPTER 02 · NOT AVAILABLE','chapter-badge'),menuText('h2','下一段故事','The next story'),menuText('p','後續章節尚未製作，將在這裡加入。','Future chapters will appear here when they are ready.'));list.append(first,next);shell.append(list,btn('← 返回主選單','← Main menu',()=>{menuPage='home';drawMenu()}));}shell.append(menuText('div','粉絲創作 · 人物對話與事件均為虛構','Fan-made · Fictional dialogue and events','menu-footer'));startScreen.append(shell)}
function requestRestart(chapter){setMode('item-ui');show('重新開始第'+chapter+'章？','Restart Chapter '+chapter+'?');p('會清除本章的物品、線索與解謎進度，另一章的進度會保留。','This clears this chapter’s items, clues and puzzle progress. The other chapter is preserved.');action('取消','Cancel',()=>$('modal').close());action('確認重新開始','Restart chapter',()=>{if(chapter===2)c2enter('confirmed');else enterChapter('confirmed')})}
function enterChapter(restart){if(restart===true){requestRestart(1);return}if(restart){const lang=s.lang;localStorage.removeItem('morton-game-v1');s={lang,version:2,finalFlow:true,stageFlow:true,clues:[],reconstructed:[],chatHistory:{},sentMessages:{},card:false,pick:false,unlocked:false,setlist:false,solved:false,setlistReported:false};}const fresh=!hasProgress();s.started=true;save();document.body.className='';$('modal').close();setMode('');if(fresh||restart)mortonChat();}
