const c2nudge=document.createElement('button');c2nudge.className='morton-nudge';c2nudge.setAttribute('aria-label','Morton');document.body.append(c2nudge);
function c2notify(){if(activeChapter!==2){c2nudge.className='morton-nudge';return}const c=C();c.promptSeen||={};const stages=['intro'];if(c.powered)stages.push('tuner');if(c.wired)stages.push('wired');if(c.overlay)stages.push('overlay');if(c.key)stages.push('key');if(c.escaped)stages.push('escaped');const newest=stages.at(-1);if(!c.promptSeen[newest]&&c.pendingPrompt!==newest){stages.forEach(id=>c.promptSeen[id]=true);c.pendingPrompt=newest;localStorage.setItem('morton-game-v1',JSON.stringify(s))}c2nudge.replaceChildren();if(!c.pendingPrompt){c2nudge.className='morton-nudge';return}c2nudge.className='morton-nudge available';let avatar=document.createElement('span');avatar.className='dialogue-avatar';avatar.setAttribute('aria-hidden','true');let copy=document.createElement('span');copy.className='nudge-copy';let name=document.createElement('strong');name.textContent='Morton';let line=document.createElement('span');line.className='nudge-line';line.textContent=t(...c2prompts[c.pendingPrompt]);let hint=document.createElement('small');hint.textContent=t('點開回應','Tap to respond');copy.append(name,line,hint);c2nudge.append(avatar,copy);c2nudge.onclick=()=>{const id=C().pendingPrompt;if(!id)return;const words=c2prompts[id];C().exchanges||=C().history.map(()=>null);C().exchanges.push(null);C().history.push([words[0],words[1]]);C().activePrompt=id;delete C().pendingPrompt;c2store();c2chat()}}
function c2reply(){const id=C().activePrompt;if(!id||C().promptReplied?.[id])return;const words=c2prompts[id];action(words[2],words[3],()=>{C().promptReplied||={};C().promptReplied[id]=true;C().exchanges||=C().history.map(()=>null);C().exchanges.push([words[2],words[3]]);C().history.push([words[4],words[5]]);c2store();c2chat()})}
function c2store(){save();c2render()}
function c2take(id){if(!c2item(id))C().items.push(id);c2store()}
function c2record(id){if(!c2has(id))C().records.push(id);c2store()}
const c2records={
 tuning:['琴架便條：登入讀取順序是 6 → 5 → 4 → 3 → 2 → 1。每條弦取一個偏差數字，不用音名。','Stand note: login order is 6 → 5 → 4 → 3 → 2 → 1. Take one deviation digit per string, not note names.'],
 photo:['10/11 排練照片：踏板由左到右是綠、藍、紅。吉他的線從右邊進入，音箱在左邊。','10/11 rehearsal photo: pedals left to right are green, blue, red. Guitar input is on the right; amp output on the left.'],
 service:['維修卡：紅＝壓縮、藍＝破音、綠＝回音。訊號先壓縮，再破音，最後回音。','Service card: red = compressor, blue = drive, green = echo. Signal goes through compression, then drive, then echo.'],
 current:['10/11 · 21:06 最終排練安排：Blue Hour → Static → First Light；速度 92 BPM。','10/11 · 21:06 final rehearsal plan: Blue Hour → Static → First Light; tempo 92 BPM.'],
 old:['10/09 舊安排：First Light → Blue Hour → Static；86 BPM。','10/09 old plan: First Light → Blue Hour → Static; 86 BPM.'],
 revision:['Jamie · 21:09：今晚換成 21:06 那版。舊速度慢了；標記紙放進節拍器旁的器材箱夾層。','Jamie · 21:09: use the 21:06 version tonight. Old tempo was too slow; overlay is in the metronome case compartment.'],
 repair:['門把的回彈扣卡住。備用鑰匙能收回鎖舌；鑰匙在三位數盒子裡。','The handle return latch is jammed. The spare key retracts the bolt; it is in the three-digit box.'],
 demo:['Morton 測試訊號：第一下短、第二下長、第三下短。錄音器以短＝1、長＝2 記錄。','Morton tests the signal: short, long, short. Recorder labels short = 1 and long = 2.'],
 audio:['錄音便條：器材箱夾層用當晚正式速度；鑰匙盒用當晚曲目次序，不用錄音檔名稱。','Recorded note: case compartment uses tonight’s final tempo; key box uses tonight’s song order, not the recording filenames.'],
 sheet:['樂譜卡：First Light／Static／Blue Hour 各有一行數字。透明片定位在左上角的雙孔。','Sheet card: First Light / Static / Blue Hour each has a row of numbers. Align overlay with the twin holes at top left.'],
 overlay:['定位後的窗口：First Light＝3、Static＝8、Blue Hour＝5。','Aligned windows reveal: First Light = 3, Static = 8, Blue Hour = 5.']};
const c2names={battery:['9V 電池','9V battery'],tuner:['調音器','Tuner'],lead:['線材組','Cable kit'],sheet:['樂譜卡','Sheet card'],overlay:['透明標記片','Overlay'],key:['備用鑰匙','Spare key']};
function c2show(view,a,b,mode='item-ui'){c2view=view;setMode(mode);show(a,b)}
function c2clue(id){p(...c2records[id]);action(c2has(id)?'✓ 已加入筆記':'加入筆記',c2has(id)?'✓ Saved':'Save clue',()=>{c2record(id);p('已保存到第二章筆記。','Saved to Chapter 2 notes.')})}
function c2input(a,b,fn,max=12){let input=document.createElement('input');input.setAttribute('aria-label',t(a,b));input.placeholder=t(a,b);input.maxLength=max;$('content').append(input);action('確認','Confirm',()=>fn(input.value.trim().toUpperCase()))}
function c2render(){if(activeChapter!==2)return;$('status').textContent=t('第二章 · 物品：','Chapter 2 · Inventory: ')+C().items.map(x=>t(...c2names[x])).join(' / ');$('phone').textContent=t('手機','Phone');$('notes').textContent=t('調查筆記','Notebook');$('reset').textContent=t('重新開始第二章','Restart Chapter 2');c2notify()}
function c2enter(restart=false){if(restart===true){requestRestart(2);return}if(restart)s.ch2=c2fresh();const fresh=!s.ch2;C();activeChapter=2;document.body.className='chapter-two';$('modal').close();setMode('');c2store();if(fresh||restart)c2intro()}
function c2intro(){c2show('intro','最後一次排練','One Last Rehearsal');p('22:17。最後一輪排練結束，你和 Morton 留下收拾。門把忽然失去回彈，門打不開了。\n\nJamie 在訊息裡提過備用鑰匙，但鑰匙盒仍沿用樂隊以前設計的解謎鎖。你們得找回那套解鎖方法。','22:17. Rehearsal is over. You and Morton stay to pack up. The door handle stops springing back; the door won’t open.\n\nJamie mentioned a spare key, but its box still uses the band’s old puzzle lock. You’ll need to recover the unlocking method.');p('物品可以帶走，也可能需要搭配使用。記錄可加入筆記；Morton 會在你找到相關線索後提供協助。','Collect items and combine them where useful. Save records to Notebook; Morton can help once you find relevant clues.');action('開始探索','Explore',()=>$('modal').close())}
function c2bag(){c2show('bag','器材袋','Equipment bag');p('袋裡是排練用的零件。','Rehearsal spares are inside.');['battery','tuner','lead'].forEach(id=>action(c2item(id)?'✓ '+c2names[id][0]:'拿取 '+c2names[id][0],c2item(id)?'✓ '+c2names[id][1]:'Take '+c2names[id][1],()=>{c2take(id);c2bag()}));if(c2item('tuner')&&c2item('battery')&&!C().powered)action('裝電池到調音器','Put battery in tuner',()=>{C().powered=true;c2store();c2bag()});if(C().powered)p('調音器已通電，可以拿到吉他旁使用。','Tuner powered. Use it by the guitar.')}
function c2guitar(){c2show('guitar','吉他架','Guitar stand');p('琴架標記的是弦號，不是數字大小。','Stand markers identify string numbers, not numeric values.');c2clue('tuning');if(C().powered){action('用調音器逐弦檢查','Check strings with tuner',()=>{let readings=c2calibration();p('調音器 · 即時偏差（cents）','Tuner · Live deviation (cents)');readings.forEach((n,i)=>p('第 '+(i+1)+' 弦：'+(n>0?'+':'')+n+' cents','String '+(i+1)+': '+(n>0?'+':'')+n+' cents'));p('螢幕顯示順序：1 → 2 → 3 → 4 → 5 → 6。這不是登入順序，請核對琴架便條。讀數已保存，再次檢查不會改變。','Display order: 1 → 2 → 3 → 4 → 5 → 6. This is not the login order; check the stand note. Readings are saved and stay the same when checked again.');C().tuned=true;c2store()})}else p('調音器還不能工作。','The tuner isn’t ready yet.');action(c2item('sheet')?'✓ 已拿取樂譜卡':'查看琴架底層',c2item('sheet')?'✓ Sheet card collected':'Inspect lower stand',()=>{c2take('sheet');c2sheet()})}
function c2sheet(){c2show('sheet','樂譜卡','Sheet card');c2clue('sheet');let grid=document.createElement('div');grid.className='c2-score';grid.innerHTML='<div>First Light &nbsp; 6 &nbsp; 3 &nbsp; 1</div><div>Static &nbsp; 8 &nbsp; 4 &nbsp; 2</div><div>Blue Hour &nbsp; 7 &nbsp; 2 &nbsp; 5</div>';$('content').append(grid);if(c2item('overlay')){action('把透明片放上樂譜','Place overlay on sheet',c2align);if(C().overlay)c2clue('overlay')}else p('左上角有兩個定位孔，單看數字沒有明確規則。','Twin alignment holes sit at top left. The numbers alone give no clear rule.')}
function c2align(){c2show('align','透明片定位','Align the overlay');p('透明片也有一組雙孔。選擇與樂譜相同的方向。','The overlay also has twin holes. Match their position on the sheet.');[['左上','Top left',true],['右上','Top right',false],['左下','Bottom left',false],['右下','Bottom right',false]].forEach(([a,b,ok])=>action(a,b,()=>{if(!ok){p('孔位不吻合，透明片放不平。','Holes don’t match; the overlay won’t sit flat.');return}C().overlay=true;c2record('overlay');c2sheet()}))}
function c2desk(){c2show('desk','STUDIO.OS','STUDIO.OS','pc-ui');if(!C().login){p('工作站鎖定。鍵盤旁的校準便條：「每條弦取偏差數字，忽略 + 和 −（例如 −4 記作 4）。按琴架便條的弦號順序連成六位數，不要按數值大小排序。」','Workstation locked. Calibration note by keyboard: “Use each string’s deviation digit, ignoring + and − (e.g. −4 becomes 4). Join six digits in the string order on the stand. Do not sort by numeric value.”');c2input('登入密碼','Login password',v=>{if(!C().tuned){p('先讓調音器工作，核對琴架上的標記。','Power the tuner and verify the guitar stand markers first.');return}if(v!==c2calibration().slice().reverse().map(Math.abs).join('')){p('登入失敗。核對弦號方向，並只取偏差的數字。','Login failed. Check string order and use only the deviation magnitudes.');return}C().login=true;c2store();c2desk()},6);return}let grid=document.createElement('div');grid.className='desktop-grid';[['排練檔案','Rehearsal files','▰',c2files],['訊息記錄','Message archive','▤',c2messages],['錄音器','Recorder','●',c2recorder]].forEach(([a,b,iconText,fn])=>grid.append(icon(a,b,iconText,fn)));$('content').append(grid)}
function c2files(){c2show('files','排練檔案','Rehearsal files','pc-ui');action('← 桌面','← Desktop',c2desk);action('10-09 / plan.txt','10-09 / plan.txt',()=>{c2show('old','10-09 / plan.txt','10-09 / plan.txt','pc-ui');c2clue('old');action('← 檔案','← Files',c2files)});action('10-11 / plan-final.txt','10-11 / plan-final.txt',()=>{c2show('current','10-11 / plan-final.txt','10-11 / plan-final.txt','pc-ui');c2clue('current');action('← 檔案','← Files',c2files)});action('10-11 / pedal-photo','10-11 / pedal-photo',()=>{c2show('photo','排練照片','Rehearsal photo','pc-ui');let pic=document.createElement('div');pic.className='c2-photo';pic.textContent='AMP ← [GREEN] ← [BLUE] ← [RED] ← GUITAR';$('content').append(pic);c2clue('photo');action('← 檔案','← Files',c2files)})}
function c2messages(){c2show('messages','工作訊息','Work messages','pc-ui');action('← 桌面','← Desktop',c2desk);c2clue('revision');p('Alex · 21:12：踏板拆下清潔了，接線規則寫在音箱的維修卡。','Alex · 21:12: pedals are off for cleaning. Wiring rules are on the amp’s service card.');p('Jamie · 21:15：門扣最近有點卡。鑰匙盒只認當晚順序，別用舊安排。','Jamie · 21:15: latch has been sticking. Key box uses tonight’s order; don’t use the old plan.')}
function c2amp(){c2show('amp','音箱與維修卡','Amp & service card');c2clue('service');p(C().wired?'接線完成，可以請 Morton 試彈。':'音箱通電，但還沒有完整的輸入訊號。',C().wired?'Wiring complete. Ask Morton to test it.':'Amp has power, but no complete input signal.');action('查看踏板板','Inspect pedalboard',c2pedals)}
function c2pedals(){c2show('pedals','踏板接線','Pedal wiring');p('三個插槽按畫面從左到右排列。每個踏板只能用一次。','Slots follow the screen, left to right. Use each pedal once.');const sels=[];['左槽','中槽','右槽'].forEach((name,i)=>{let label=document.createElement('label');label.textContent=t(name,['Left slot','Middle slot','Right slot'][i]);let select=document.createElement('select');select.setAttribute('aria-label',label.textContent);select.innerHTML='<option value="">—</option><option value="green">'+t('綠','Green')+'</option><option value="blue">'+t('藍','Blue')+'</option><option value="red">'+t('紅','Red')+'</option>';select.value=C().pedals?.[i]||'';label.append(select);$('content').append(label);sels.push(select)});let flow=document.createElement('select');flow.setAttribute('aria-label',t('訊號方向','Signal direction'));flow.innerHTML='<option value="">'+t('選擇訊號方向','Choose signal direction')+'</option><option value="rl">'+t('吉他從右進 → 音箱從左出','Guitar in right → amp out left')+'</option><option value="lr">'+t('吉他從左進 → 音箱從右出','Guitar in left → amp out right')+'</option>';flow.value=C().flow||'';$('content').append(flow);action('使用線材並測試','Use cables & test',()=>{if(!c2item('lead')){p('你還沒有線材組。','You don’t have the cable kit.');return}const values=sels.map(x=>x.value);C().pedals=values;C().flow=flow.value;if(!c2has('photo')||!c2has('service')){c2store();p('先把排練照片和維修卡加入筆記，才能確認接線。','Save the rehearsal photo and service card to verify the wiring.');return}if(values.join(',')!=='green,blue,red'||flow.value!=='rl'){C().wired=false;c2store();p('訊號不通。實際擺放順序與訊號經過順序是兩回事，核對入口。','No signal. Physical placement and signal order differ. Check the input side.');return}C().wired=true;c2store();p('✓ 訊號燈亮了。可以請 Morton 試彈。','✓ Signal light is on. Ask Morton to test it.');action('找 Morton','Talk to Morton',c2chat)})}
function c2speech(thread,name,text,player=false){let row=document.createElement('div');row.className='dialogue-row'+(player?' player':'');let avatar=document.createElement('span');avatar.className='dialogue-avatar';avatar.setAttribute('aria-hidden','true');if(player)avatar.textContent='•';let body=document.createElement('div');body.className='dialogue-body';let label=document.createElement('span');label.className='dialogue-name';label.textContent=name;let bubble=document.createElement('p');bubble.className='dialogue-bubble';bubble.textContent=text;body.append(label,bubble);row.append(avatar,body);thread.append(row)}
function c2chat(){let revised=false;C().history.forEach(line=>{if(line[0]==='Morton：「21:06 那份。後來我們把 Blue Hour 放前面，舊的速度也改掉了。」'){line[0]='Morton：「當晚改過幾次，電腦裡應該留著最後的記錄。」';revised=true}if(line[1]==='Morton: “the 21:06 one. we moved Blue Hour to the front and changed the old tempo.”'){line[1]='Morton: “we changed things a few times that night. the final notes should still be on the laptop.”';revised=true}});if(revised)c2store();c2show('chat','Morton','Morton','dialogue-ui');let thread=document.createElement('div');thread.className='dialogue-thread';$('content').append(thread);c2speech(thread,'Morton',t('我們慢慢來，先看看有哪些東西能用。','we got this. let’s see what we can use first.'));C().history.forEach(([a,b],i)=>{const reply=C().exchanges?.[i];if(reply)c2speech(thread,t('你','You'),t(...reply),true);c2speech(thread,'Morton',t(a,b).replace(/^Morton[：:]\s*[「“]?/,'').replace(/[」”]$/,''))});if(C().wired&&!C().demo)action('接好了，你可以試彈嗎？','wired it up. can you test it?',()=>{C().demo=true;C().exchanges||=C().history.map(()=>null);C().exchanges.push(['接好了，你可以試彈嗎？','wired it up. can you test it?']);C().history.push(['Morton：「嗯，聲音有了。試三下：短、長、短。錄音器上的 1 和 2 應該就是這個。」','Morton: “yep, signal’s good. three hits: short, long, short. pretty sure that’s what 1 and 2 on the recorder mean.”']);c2record('demo');c2chat();c2tone([1,2,1])});if(c2has('current')&&c2has('revision')&&!C().confirmed)action('哪個排練版本才是今晚的？','which rehearsal version did we use?',()=>{C().confirmed=true;C().exchanges||=C().history.map(()=>null);C().exchanges.push(['哪個排練版本才是今晚的？','which rehearsal version did we use?']);C().history.push(['Morton：「當晚改過幾次，電腦裡應該留著最後的記錄。」','Morton: “we changed things a few times that night. the final notes should still be on the laptop.”']);c2store();c2chat()});if(C().overlay&&!C().orderTalk)action('透明片找出數字了。','got the numbers from the overlay.',()=>{C().orderTalk=true;C().exchanges||=C().history.map(()=>null);C().exchanges.push(['透明片找出數字了。','got the numbers from the overlay.']);C().history.push(['Morton：「那就按今晚真正彈的順序排，不是紙上印的順序。」','Morton: “then put them in the order we actually played tonight, not the order on the paper.”']);c2store();c2chat()});c2reply();action('回到房間','Back to room',()=>$('modal').close())}
function c2phone(){c2show('phone','Messages','Messages','phone-ui');contact('Jamie','',()=>{c2show('jamie','Jamie','Jamie','phone-ui');p('Jamie · 22:18：「抱歉！門扣又卡了？備用鑰匙在牆上盒子裡。那個是我們以前的解謎盒，要照今晚排練資料開。」','Jamie · 22:18: “ugh, latch stuck again? spare key’s in the wall box. it’s our old puzzle box—use tonight’s rehearsal stuff to open it.”');action('← 聯絡人','← Contacts',c2phone)})}
function c2tone(lengths){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const context=new Audio();let time=context.currentTime+.05;lengths.forEach(n=>{let osc=context.createOscillator(),gain=context.createGain();osc.type='triangle';osc.frequency.value=220;gain.gain.value=.08;osc.connect(gain);gain.connect(context.destination);osc.start(time);osc.stop(time+.15*n);time+=.15*n+.18});setTimeout(()=>context.close(),2500)}
function c2recorder(){c2show('recorder','錄音器','Recorder','pc-ui');action('← 桌面','← Desktop',c2desk);p('控制面板：短音＝1、長音＝2。存檔需三下測試訊號。','Panel: short = 1, long = 2. Archive requires three test hits.');if(!C().recorder){c2input('三下訊號','Three test hits',v=>{if(!C().demo){p('還沒有現場測試訊號，先請 Morton 試彈。','No live test signal yet. Ask Morton to test the setup.');return}if(v!=='121'){p('訊號不符。核對短音與長音。','Signal mismatch. Check short and long hits.');return}C().recorder=true;c2store();c2recorder()},3)}else{action('播放測試訊號','Play test signal',()=>c2tone([1,2,1]));c2clue('audio');p('錄音檔名：01_FirstLight / 02_Static / 03_BlueHour\n檔名是建立順序，並非演奏順序。','Files: 01_FirstLight / 02_Static / 03_BlueHour\nNames follow creation order, not performance order.')}}
function c2metro(){c2show('metro','節拍器與器材箱','Metronome & equipment case');p('節拍器顯示 86 BPM，背面貼著 10/09 舊設定。器材箱的前層裝了數字鎖，刻字：「最後留下的節拍。」','The metronome still displays 86 BPM, labelled 10/09 — an old setting. A numeric lock secures the case’s front compartment. Engraving: “The last beat we left behind.”');if(C().drawer){p('夾層已打開。','Compartment open.');action(c2item('overlay')?'✓ 透明標記片':'拿取透明標記片',c2item('overlay')?'✓ Overlay':'Take overlay',()=>{c2take('overlay');c2metro()});return}c2input('BPM','BPM',v=>{if(!C().recorder||!c2has('audio')||!c2has('current')||!c2has('revision')){p('需要錄音便條與核對過的當晚記錄，才能確定該用哪個速度。','Use the recorded note and verified current records to establish the correct tempo.');return}if(v!=='92'){p(v==='86'?'86 是 10/09 的舊速度。請用錄音便條核對 10/11 最終安排。':'夾層沒有打開。這是最後確認的速度嗎？',v==='86'?'86 belongs to the old 10/09 plan. Cross-check the recorded note with the final 10/11 plan.':'Still locked. Is this the final confirmed tempo?');return}C().drawer=true;c2store();c2metro()},3)}
function c2box(){c2show('box','備用鑰匙盒','Spare-key box');p('三位數鎖，盒面貼著一小段透明片形狀。','Three-digit lock. An overlay-shaped sticker sits on the lid.');if(C().key){p('盒子已打開。備用鑰匙在你的物品裡。','Box open. Spare key is in your inventory.');return}c2input('三位數','Three digits',v=>{if(!C().overlay||!c2has('current')||!c2has('revision')||!c2has('audio')){p('還缺解鎖依據：透明片、當晚安排、版本確認與錄音便條。','Missing basis: aligned overlay, tonight’s plan, revision confirmation and recorded note.');return}if(v!=='583'){p('鎖沒有動。核對數字來源與今晚的曲目順序。','No movement. Check the numbers and tonight’s song order.');return}C().key=true;c2take('key');c2box();action('前往門口','Go to door',c2door)},3)}
function c2door(){c2show('door','練習室門','Studio door');c2clue('repair');if(c2item('key'))action('用備用鑰匙收回鎖舌','Retract bolt with spare key',()=>{C().escaped=true;c2store();c2show('ending','第二章完成','Chapter 2 complete');p('鎖舌收回，門終於打開。Morton 抱起琴盒，回頭看了眼練習室。\n\n「下次我們先確認門能打開，再收拾吧。」','The bolt retracts. The door finally opens. Morton picks up his guitar case and looks back at the studio.\n\n“next time, let’s check the door before we pack up.”');p('✓ 最後一次排練 · 完成\n接線、錄音、節拍與透明片共同找出了備用鑰匙。','✓ One Last Rehearsal · Complete\nWiring, recording, tempo and overlay led you to the spare key.');action('返回章節選單','Back to chapters',()=>{openMenu();menuPage='chapters';drawMenu()})});else p('門扣卡住了，不能直接拉開。','Latch is stuck; pulling won’t open it.')}
function c2notes(section='clues'){c2show('notes','第二章筆記','Chapter 2 notes','notebook-ui');const oldTabs=$('content').querySelector('.notebook-tabs');if(oldTabs)oldTabs.remove();let tabs=document.createElement('nav');tabs.className='notebook-tabs';[['clues','線索','Clues'],['items','物品','Items'],['progress','解謎進度','Progress']].forEach(([id,a,b])=>{let e=btn(a,b,()=>c2notes(id));e.className='notebook-tab'+(section===id?' selected':'');tabs.append(e)});$('content').prepend(tabs);if(section==='clues'){if(!C().records.length)p('筆記還是空的。','No saved clues yet.');C().records.forEach(id=>p(...c2records[id]))}else if(section==='items'){C().items.forEach(id=>action(...c2names[id],()=>{if(id==='sheet'||id==='overlay')c2sheet();else if(id==='key')c2door();else c2bag()}));}else{[[C().powered,'讓調音器工作','Power the tuner'],[C().login,'進入工作站','Access workstation'],[C().wired,'恢復訊號','Restore signal'],[C().recorder,'解鎖錄音','Unlock recording'],[C().drawer,'打開節拍夾層','Open metronome case compartment'],[C().overlay,'定位透明片','Align overlay'],[C().key,'取得備用鑰匙','Find spare key'],[C().escaped,'離開練習室','Leave studio']].forEach(([ok,a,b])=>p((ok?'✓ ':'○ ')+a,(ok?'✓ ':'○ ')+b))}}
function c2hint(){let stage=!C().powered?'power':!C().login?'login':!C().wired?'wire':!C().demo?'demo':!C().recorder?'record':!C().drawer?'tempo':!C().overlay?'overlay':!C().key?'key':'door';const hints={power:[['留意器材袋裡的小零件。','Check the spares in the equipment bag.'],['調音器需要電源。','The tuner needs power.'],['拿取電池和調音器，在器材袋窗口選「裝電池到調音器」。','Take battery and tuner, then use “Put battery in tuner” in the bag.']],login:[['琴架和登入提示說的是同一個方向。','Guitar stand and login hint use the same direction.'],['調音器列出各弦偏差；琴架指定輸入順序，電腦便條說明如何處理符號。','The tuner gives string deviations; the stand gives entry order; the computer note explains the signs.'],['調音器從第一弦列到第六弦；倒過來讀，只取數字，不輸入正負號。','Tuner lists strings 1 to 6. Read in reverse and enter just the numbers, without signs.']],wire:[['照片與維修卡提供不同部分。','Photo and service card give different pieces.'],['畫面的左到右，不等於訊號的先到後。','Left-to-right placement differs from signal sequence.'],['保存照片和維修卡，拿線材。左綠、中藍、右紅；吉他從右進、音箱從左出。','Save photo and service card, take cables. Left green, middle blue, right red; input right, output left.']],demo:[['訊號通了，找懂器材的人協助。','Signal is live. Ask someone to help test it.'],['現在可以請 Morton 試彈。','You can now ask Morton to test the setup.'],['點房間裡的 Morton，請他試彈。','Click Morton in the room and ask him to test it.']],record:[['錄音器面板解釋了長短音。','Recorder panel explains short and long hits.'],['把 Morton 的三下試音轉成 1 和 2。','Translate Morton’s three hits into 1 and 2.'],['短、長、短＝121。解鎖後保存錄音便條。','Short, long, short = 121. Save the recorded note after unlocking.']],tempo:[['別把舊排練安排當成今晚的。','Don’t mistake the old plan for tonight’s.'],['保存最終安排、版本訊息和錄音便條；它們共同指定速度。','Save final plan, revision message and recorded note; together they specify the tempo.'],['10/11 21:06 的正式速度是 92 BPM。在節拍器輸入 92。','10/11 21:06 final tempo is 92 BPM. Enter 92 at the metronome.']],overlay:[['回到早先拿到的樂譜。','Return to the sheet you found earlier.'],['拿夾層裡的透明片，比對兩個定位孔。','Take the overlay from the compartment and match the twin holes.'],['筆記 → 物品 → 樂譜卡 → 放透明片 → 左上。','Notes → Items → Sheet card → place overlay → top left.']],key:[['數字有了，還需要次序。','You have the numbers; you still need their order.'],['按當晚正式曲目順序，不按紙上或檔名順序。','Use tonight’s final song order, not sheet or filename order.'],['Blue Hour 5 → Static 8 → First Light 3。鑰匙盒輸入 583。','Blue Hour 5 → Static 8 → First Light 3. Enter 583 in the key box.']],door:[['看看門鎖。','Check the door lock.'],['用你剛拿到的物品。','Use the item you just collected.'],['點門，選用備用鑰匙。','Click the door and use the spare key.']]};let level=C().hints[stage]||0;c2show('hint','提示','Hint');p('提示 '+(level+1)+'/3','Hint '+(level+1)+'/3');p(...hints[stage][level]);if(level<2)action('再多一點提示','Reveal next hint',()=>{C().hints[stage]=level+1;c2store();c2hint()})}
const c2room=document.createElement('div');c2room.id='studio-room';c2room.className='studio-room';document.querySelector('main').append(c2room);
[['desk',0,25,23,30,c2desk,'工作站','Workstation'],['guitar',30,18,13,24,c2guitar,'吉他架','Guitar stand'],['amp',67,34,14,16,c2amp,'音箱','Amp'],['metro',24,32,10,21,c2metro,'節拍器','Metronome'],['pedals',6,66,22,23,c2pedals,'踏板板','Pedalboard'],['bag',79,60,20,28,c2bag,'器材袋','Equipment bag'],['box',70,19,6,11,c2box,'鑰匙盒','Key box'],['door',76,5,18,47,c2door,'練習室門','Studio door'],['morton',47,44,8,29,c2chat,'Morton','Morton']].forEach(([id,left,top,width,height,fn,a,b])=>{let e=document.createElement('button');e.className='hot';e.dataset.c2=id;e.style.cssText=`left:${left}%;top:${top}%;width:${width}%;height:${height}%`;e.setAttribute('aria-label',t(a,b));e.onclick=fn;c2room.append(e)});
const firstEnter=enterChapter;enterChapter=function(restart){const secondSave=s.ch2;activeChapter=1;firstEnter(restart);if(secondSave&&!s.ch2){s.ch2=secondSave;save()}if(document.body.className==='chapter-two')activeChapter=2};
const firstOpenMenu=openMenu;openMenu=function(){activeChapter=0;firstOpenMenu()};menuButton.onclick=openMenu;
const firstRender=render;render=function(){firstRender();c2render()};
const firstPhone=phone,firstNotebook=notebook,firstHint=$('hint').onclick;
$('phone').onclick=()=>activeChapter===2?c2phone():firstPhone();$('notes').onclick=()=>activeChapter===2?c2notes():firstNotebook();$('hint').onclick=()=>activeChapter===2?c2hint():firstHint();$('reset').onclick=()=>activeChapter===2?c2enter(true):enterChapter(true);
$('lang').onclick=()=>{s.lang=s.lang==='zh'?'en':'zh';save();if(activeChapter===2&&$('modal').open){const routes={intro:c2intro,bag:c2bag,guitar:c2guitar,sheet:c2sheet,align:c2align,desk:c2desk,files:c2files,messages:c2messages,amp:c2amp,pedals:c2pedals,chat:c2chat,phone:c2phone,recorder:c2recorder,metro:c2metro,box:c2box,door:c2door,notes:c2notes,hint:c2hint};if(routes[c2view])routes[c2view]();else c2desk()}else $('modal').close()};
const firstDrawMenu=drawMenu;drawMenu=function(){firstDrawMenu();if(menuPage!=='chapters')return;let list=startScreen.querySelector('.chapter-list');let locked=list.querySelector('.locked');if(locked)locked.remove();let card=document.createElement('article');card.className='chapter-card';card.append(menuText('div','CHAPTER 02 · '+(s.ch2?.escaped?'已完成':s.ch2?'進行中':'可遊玩'),'CHAPTER 02 · '+(s.ch2?.escaped?'COMPLETE':s.ch2?'IN PROGRESS':'AVAILABLE'),'chapter-badge'),menuText('h2','最後一次排練','One Last Rehearsal'),menuText('p','你和 Morton 被困在練習室。\n組合物品、核對記錄，找回備用鑰匙。','You and Morton are stuck in the rehearsal studio.\nCombine items and cross-check records to recover the spare key.'));let begin=btn(s.ch2?'繼續第二章':'開始第二章',s.ch2?'Continue Chapter 2':'Start Chapter 2',()=>c2enter());begin.className='menu-primary';card.append(begin);if(s.ch2)card.append(btn('重新開始第二章','Restart Chapter 2',()=>c2enter(true)));card.append(menuText('div','難度提升 · 三層提示 · 無倒數 · 獨立保存','More challenging · Three hint levels · No timer · Separate progress','chapter-note'));list.append(card)};
