const c3has=id=>D().clues.includes(id);function c3save(){save();c3render()}
function c3show(view,a,b,mode='item-ui'){c3view=view;setMode(mode);show(a,b)}
function c3clue(id){p(...c3evidence[id]);action(c3has(id)?'✓ 已加入筆記':'加入筆記',c3has(id)?'✓ Saved':'Save clue',()=>{if(!c3has(id))D().clues.push(id);c3save();p('已保存到第三章筆記。','Saved to Chapter 3 notes.')})}
function c3enter(restart=false){if(restart===true){requestRestart(3);return}if(restart)s.ch3=c3fresh();const fresh=!s.ch3;D();activeChapter=3;document.body.className='chapter-three';$('modal').close();setMode('');c3save();if(fresh||restart)c3intro()}
function c3intro(){c3show('intro','拿錯的背包','The Wrong Backpack');p('18:45，城堡廣場。你和 Morton 剛拍完照片，準備找地方等煙花。\n\n他打開背包拿充電線，卻發現拉鏈上的黃色燈泡變成了藍色星星。這不是他的包。你們得先找到失主，再找回自己的背包。','18:45, castle plaza. You and Morton have finished taking photos and are choosing a spot for the fireworks.\n\nHe reaches for a charging cable, then notices a blue star where his yellow bulb charm should be. This isn’t his bag. Find its owner and recover his.');p('用地點按鈕移動；比對照片、收據與人物說法。這是一段虛構的樂園故事，沒有真實倒數。','Use location buttons to explore. Compare photos, receipts and accounts. This is a fictional park story, with no real countdown.');action('開始探索','Explore',()=>$('modal').close())}
function c3bag(){c3show('bag','陌生背包','Unfamiliar backpack');c3clue('tag');action('查看袋口半張收據','Inspect half receipt',()=>{c3show('slip','半張收據','Half receipt');c3clue('slip')});action('和 Morton 說話','Talk to Morton',c3chat)}
function c3bench(){c3show('bench','長椅附近','By the bench');c3clue('spill');action('和旁邊的 Eli 說話','Talk to Eli nearby',()=>{c3show('eli','Eli','Eli','dialogue-ui');let thread=document.createElement('div');thread.className='dialogue-thread';$('content').append(thread);c2speech(thread,'Eli',t('不好意思，這裡剛才弄濕了。','sorry, i spilled a drink here earlier.'));let face=thread.querySelector('.dialogue-avatar');face.style.background='#49566a';face.textContent='E';c3clue('eli')});action('回看手機照片','Review phone photos',c3photos)}
function c3shop(){c3show('shop','紀念品店','Souvenir shop');p('玻璃窗反射著長椅。櫃檯陳列黃色燈泡與藍色星星吊飾，兩款都能掛在同款背包上。','The window reflects the bench. Yellow bulb and blue star charms sit on the counter; both fit the same model of backpack.');if(c3has('slip'))action('用半張收據核對交易','Match half receipt to transaction',()=>{c3show('shoprecord','交易副本','Transaction copies');c3clue('shop')});else p('店員：「要查交易，先給我看訂單編號或收據。」','Clerk: “To check a transaction, I’ll need an order number or receipt.”');action('查看窗邊照片','Check window photo',c3photos)}
function c3services(){c3show('services','服務處','Guest Services');action('查看失物登記','Check lost-property log',()=>{c3show('claim','失物登記','Lost-property log');c3clue('claim')});action('詢問 Theo 的清潔記錄','Ask Theo about cleanup',()=>{c3show('cleanup','Theo','Theo','dialogue-ui');c3clue('cleanup')});if(c3has('tag')&&c3has('shop'))action('聯絡背包失主 Nora','Contact bag owner Nora',()=>{c3show('nora','Nora','Nora','phone-ui');c3clue('nora')});else p('先用姓名卡和交易副本確認失主，職員才能協助聯絡。','Verify the owner using the name tag and transaction copy before staff can help contact them.');if(!D().reunited)action('認領 Morton 的背包','Claim Morton’s backpack',c3claim);else p('兩個背包已物歸原主。','Both bags are back with their owners.')}
function c3claim(){c3show('collect','認領背包','Collect backpack');const needed=['own','claim','nora'];const missing=needed.filter(id=>!c3has(id));if(missing.length){p('還需要核對並保存：','Verify and save these first:');missing.forEach(id=>p(...c3evidence[id]));return}p('職員：「請指出吊飾，再提供對應的購買訂單。」','Staff: “Identify the charm and provide its matching purchase order.”');[['藍色星星 · N17','Blue star · N17',false],['黃色燈泡 · M12','Yellow bulb · M12',true],['黃色燈泡 · N17','Yellow bulb · N17',false]].forEach(([a,b,ok])=>action(a,b,()=>{if(!ok){p('吊飾與訂單不吻合，請核對手機收據。','Charm and order don’t match. Check the phone receipt.');return}D().reunited=true;c3save();p('Morton 的背包領回了，Nora 也拿回星星吊飾的背包。但誰移動了它們，為什麼？','Morton’s bag is returned, and Nora gets her star-charm bag back. But who moved them, and why?');action('整理事件經過','Reconstruct events',c3solve)}))}
