const c3lines={start:['等等，我拿錯包了。我的吊飾不是這個，看看有沒有名字？','wait, this isn’t my bag. mine has a different charm. is there a name on it?', '你的吊飾是什麼？','what was your charm?', '黃色的小燈泡。買項鍊的時候一起拿的，收據還在手機裡。','a little yellow bulb. got it with the necklace. receipt’s still on my phone.'],tag:['找到名字了？那我們先確認一下。','found a name? let’s make sure we’ve got the right person.', '還有半張收據。','there’s half a receipt too.', '店就在旁邊，可以拿編號去問問。','shop’s right there. could ask them to check the order number.'],photos:['等等，兩張照片裡的包好像不在同一個位置。','wait, the bags aren’t in the same places in those photos.', '你當時拿的是哪邊？','which side did you pick yours up from?', '18:40 回去時拿了長椅左邊那個。我以為還是拍照前放的地方，沒再看吊飾。','went back at 18:40, took the one on the left. thought it was where i’d left it before the photo. didn’t check the charm.'],return:['找回來了。充電線也在，終於能鬆口氣。','got it back. charging cable’s here too. that’s a relief.', '下次先看吊飾。','check the charm next time.', '記住了。今天這串燈已經夠顯眼，背包倒沒看清。','lesson learned. wearing all these lights and still missed the bag charm.'],end:['還趕得上煙花。走吧，這次我拿好背包。','still in time for the fireworks. c’mon, i’ve got the bag this time.', '先拍一張沒有背包疑案的合照。','one photo without a backpack mystery first.', '可以。項鍊還亮著，剛好。','deal. necklace is still glowing, too.']};
const c3nudge=document.createElement('button');c3nudge.className='morton-nudge c3-nudge';document.body.append(c3nudge);
function c3notify(){const d=D(),ids=['start'];if(c3has('tag'))ids.push('tag');if(c3has('before')&&c3has('after'))ids.push('photos');if(d.reunited)ids.push('return');if(d.solved)ids.push('end');const id=ids.at(-1);if(!d.read[id]&&d.pending!==id){ids.forEach(x=>d.read[x]=true);d.pending=id;localStorage.setItem('morton-game-v1',JSON.stringify(s))}c3nudge.replaceChildren();c3nudge.className='morton-nudge c3-nudge'+(d.pending?' available':'');if(!d.pending)return;let face=document.createElement('span');face.className='dialogue-avatar c3-avatar';let text=document.createElement('span');text.className='nudge-copy';text.textContent='Morton · '+t(...c3lines[d.pending]);c3nudge.append(face,text);c3nudge.onclick=()=>{const id=D().pending;if(!id)return;D().history.push([c3lines[id][0],c3lines[id][1]]);D().replies.push(null);D().active=id;delete D().pending;c3save();c3chat()}}
function c3chat(){if(D().pending){const id=D().pending;D().history.push([c3lines[id][0],c3lines[id][1]]);D().replies.push(null);D().active=id;delete D().pending;c3save()}c3show('chat','Morton','Morton','dialogue-ui c3-dialogue');let thread=document.createElement('div');thread.className='dialogue-thread';$('content').append(thread);if(!D().history.length)c2speech(thread,'Morton',t(...c3lines.start));D().history.forEach(([a,b],i)=>{if(D().replies[i])c2speech(thread,t('你','You'),t(...D().replies[i]),true);c2speech(thread,'Morton',t(a,b))});const id=D().active;if(id&&!D().chatDone[id]){const words=c3lines[id];action(words[2],words[3],()=>{D().chatDone[id]=true;D().history.push([words[4],words[5]]);D().replies.push([words[2],words[3]]);c3save();c3chat()})}if(c3has('before')&&c3has('after')&&!D().pickup){action('你回來拿包時有核對吊飾嗎？','did you check the charm when you picked it up?',()=>{D().pickup=true;if(!c3has('pickup'))D().clues.push('pickup');D().history.push([c3lines.photos[4],c3lines.photos[5]]);D().replies.push(['你回來拿包時有核對吊飾嗎？','did you check the charm when you picked it up?']);c3save();c3chat()})}action('回到廣場','Back to exploring',()=>$('modal').close())}
