function c3solve(){c3show('solve','背包去了哪裡？','Where did the bags go?');if(D().solved){c3ending();return}p('用記錄支持每一步，再還原背包的去向。','Support each step with records, then reconstruct the bags’ path.');const questions=[['星星背包屬於誰？','Who owns the star-charm bag?',['Morton','Nora','Eli']],['誰移動了背包？','Who moved the bags?',['Nora','Theo','Eli']],['為什麼移動？','Why were they moved?',[t('避開飲料水漬','Keep them dry'),t('偷走物品','Steal something'),t('交換禮物','Exchange gifts')]],['移動發生在何時？','When were they moved?',['18:34','18:38','18:42']]];let selects=[];questions.forEach(([a,b,opts])=>{let label=document.createElement('label');label.textContent=t(a,b);let sel=document.createElement('select');let empty=document.createElement('option');empty.value='';empty.textContent='—';sel.append(empty);opts.forEach((x,i)=>{let o=document.createElement('option');o.value=String(i);o.textContent=x;sel.append(o)});label.append(sel);$('content').append(label);selects.push(sel)});action('核對還原','Verify reconstruction',()=>{const needed=['tag','slip','shop','before','after','spill','eli','cleanup','nora','claim','own','pickup'];let missing=needed.filter(id=>!c3has(id));if(missing.length){p('還缺已保存的支持記錄：','Save these supporting records first:');missing.forEach(id=>p(...c3evidence[id]));return}if(!D().reunited){p('先核對並領回背包，確認最後的去向。','Collect and verify the bags first to establish their final destination.');return}if(selects.map(x=>x.value).join(',')!=='1,1,0,1'){p('有一項與照片、交易或工作記錄不符。核對人物、目的和時間。','One answer conflicts with the photos, transaction or work log. Check person, purpose and time.');return}D().solved=true;c3save();c3ending()})}
function c3ending(){c3show('ending','煙花之前','Before the Fireworks');p('18:34：你們拍照，兩個背包留在長椅。\n18:37：Eli 碰倒飲料。\n18:38：Theo 將背包移到乾處，原來的位置改變了。\n18:40：Morton 按原來位置拿走 Nora 的星星背包。\n18:42：Nora 把留下的黄色燈泡背包交到服務處。\n\n兩個包都找回來了。這次沒有偷竊，只有一場因位置改變而起的誤會。','18:34: photos taken; two bags stay on the bench.\n18:37: Eli spills a drink.\n18:38: Theo moves the bags to dry spots, changing their positions.\n18:40: Morton picks up Nora’s star-charm bag from his original spot.\n18:42: Nora takes the remaining yellow-bulb bag to Guest Services.\n\nBoth bags are returned. No theft—just a mix-up after their positions changed.');p('城堡的燈光亮起。Morton 把背包掛在胸前：「這次總不會拿錯了吧。」','Castle lights glow. Morton swings the bag to his front: “can’t mix it up now, right?”');action('和 Morton 說話','Talk to Morton',()=>{c3nudge.onclick();c3chat()});action('返回主選單','Back to menu',openMenu)}
function c3hint(){c3show('hint','調查方向','Investigation hint');let pair=!c3has('tag')?['先看背包姓名卡與袋口收據。','Check the name tag and half receipt.']:!c3has('shop')?['拿半張收據到紀念品店核對交易，保存副本。','Take the half receipt to the shop and save the matching transaction.']:!c3has('before')||!c3has('after')?['手機相簿有兩張不同時間的照片，分別保存。','Save both differently timed photos in the phone album.']:!c3has('cleanup')||!c3has('eli')?['長椅的水漬、Eli 的說法與 Theo 的工作記錄可互相核對。','Compare the spill, Eli’s account and Theo’s work log.']:!c3has('nora')||!c3has('claim')?['到服務處保存失物記錄，再聯絡 Nora。','At Guest Services, save the property log and contact Nora.']:!c3has('own')?['手機裡有 Morton 自己的購買收據。','Morton’s purchase receipt is on the phone.']:!D().reunited?['認領黄色燈泡背包，核對 Morton 的購買訂單。','Claim the yellow-bulb bag using Morton’s matching purchase order.']:!c3has('pickup')?['直接問 Morton 回來拿包時有沒有核對吊飾。','Ask Morton if he checked the charm when collecting the bag.']:['回到筆記還原經過：失主、移動的人、原因與時間。','Reconstruct in Notebook: owner, mover, reason and time.'];p(...pair);if(D().hints>=1)p('照片先後位置不同，不代表失主改變；橙色圍裙與清潔記錄指向同一個人。','Different positions do not mean different owners. The orange apron and cleanup log point to the same person.');if(D().hints>=2)p('Nora 的星星背包；Theo 在 18:38 為避開水漬移動兩個包。黄色燈泡背包用 M12 認領。','Nora owns the star bag; Theo moved both bags at 18:38 to keep them dry. Claim the yellow-bulb bag with M12.');if(D().hints<2)action('再多一點提示','More help',()=>{D().hints++;c3save();c3hint()})}
