const priorHome3=deviceHome.onclick;deviceHome.onclick=()=>activeChapter===3?c3phone():priorHome3();const priorMenu3=drawMenu;drawMenu=function(){priorMenu3();if(menuPage!=='chapters')return;let list=startScreen.querySelector('.chapter-list'),card=document.createElement('article');card.className='chapter-card';card.append(menuText('div','CHAPTER 03 · '+(s.ch3?.solved?'已完成':s.ch3?'進行中':'可遊玩'),'CHAPTER 03 · '+(s.ch3?.solved?'COMPLETE':s.ch3?'IN PROGRESS':'AVAILABLE'),'chapter-badge'),menuText('h2','拿錯的背包','The Wrong Backpack'),menuText('p','夜晚的樂園，兩個相同的背包。\n與 Morton 比對照片、收據與人物說法。','A park at night. Two identical backpacks.\nCompare photos, receipts and accounts with Morton.'));let begin=btn(s.ch3?'繼續第三章':'開始第三章',s.ch3?'Continue Chapter 3':'Start Chapter 3',()=>c3enter());begin.className='menu-primary';card.append(begin);if(s.ch3)card.append(btn('重新開始第三章','Restart Chapter 3',()=>c3enter(true)));card.append(menuText('div','多區域探索 · 主動對話 · 無倒數 · 獨立保存','Multiple locations · Proactive dialogue · No timer · Separate save','chapter-note'));list.append(card)};openMenu();
