function pcRoot(){return activeChapter===2?c2desk():desk()}
function pcLabel(type){return t(...({files:['檔案','Files'],mail:['郵件','Mail'],trash:['垃圾桶','Trash'],chat:['Work Chat','Work Chat'],document:['文件預覽','Document preview']})[type])}
function pcBindPreview(back){$('content').querySelectorAll('button').forEach(button=>{if(button.pcWrapped)return;button.pcWrapped=true;const handler=button.onclick;if(!handler)return;button.onclick=function(event){handler.call(this,event);if(uiMode==='pc-ui'&&$('modal').open&&!document.getElementById('pc-app-layout')){pcFrame('document',$('title').textContent,{back});pcBindPreview(back)}}})}
function pcFrame(type,title,{rows=[],selected=-1,onSelect=null,back=null,status=''}={}){pcUnmount();const content=$('content'),layout=document.createElement('div');layout.id='pc-app-layout';layout.className=type==='chat'?'pc-chat-layout':'';const toolbar=document.createElement('div');toolbar.className='pc-window-toolbar';toolbar.append(pcGlyph(type==='files'?'folder':type));const name=document.createElement('strong');name.textContent=title;toolbar.append(name);const path=document.createElement('span');path.className='pc-path';path.textContent=(activeChapter===2?'STUDIO':'CREW')+' / '+pcLabel(type);toolbar.append(path);const main=document.createElement('div');main.className='pc-window-main';const sidebar=document.createElement('nav');sidebar.className='pc-window-sidebar';sidebar.setAttribute('aria-label',t('電腦應用程式','Computer applications'));const caption=document.createElement('p');caption.className='pc-sidebar-label';caption.textContent=type==='mail'?t('郵件匣','MAILBOXES'):t('工作站','WORKSPACE');sidebar.append(caption);const routes=type==='mail'?[['mail',t('收件匣','Inbox'),mail,'mail']]:activeChapter===2?[['folder',t('排練檔案','Files'),c2files,'files'],['chat','Work Chat',c2messages,'chat'],['record',t('錄音器','Recorder'),c2recorder,'recorder']]:[['folder',t('檔案','Files'),files,'files'],['chat','Work Chat',workChat,'chat'],['mail',t('郵件','Mail'),mail,'mail'],['trash',t('垃圾桶','Trash'),trash,'trash']];for(const [glyph,label,fn,key] of routes){const button=document.createElement('button');button.type='button';button.title=label;button.setAttribute('aria-label',label);if(key===type)button.setAttribute('aria-current','page');const span=document.createElement('span');span.className='pc-nav-label';span.textContent=label;button.append(pcGlyph(glyph),span);button.onclick=fn;sidebar.append(button)}const home=document.createElement('button');home.title=t('返回桌面','Back to desktop');home.setAttribute('aria-label',home.title);home.textContent='⌂';home.onclick=pcRoot;sidebar.append(home);if(back){const backButton=btn('← 返回','← Back',back);backButton.title=t('返回上一層','Back to previous folder');backButton.setAttribute('aria-label',backButton.title);sidebar.append(backButton)}main.append(sidebar);if(rows.length){const list=document.createElement('nav');list.className='pc-window-list';list.setAttribute('aria-label',type==='mail'?t('收件匣','Inbox'):type==='chat'?t('工作對話','Work conversations'):t('檔案列表','File list'));rows.forEach((row,index)=>{const button=document.createElement('button');button.className='pc-list-row';button.type='button';button.setAttribute('aria-current',String(index===selected));button.append(pcGlyph(row.icon||'document'));const copy=document.createElement('span');copy.className='pc-row-copy';const name=document.createElement('strong');name.textContent=row.label;copy.append(name);if(row.detail){const detail=document.createElement('small');detail.textContent=row.detail;copy.append(detail)}button.append(copy);button.onclick=()=>onSelect?.(index);list.append(button)});main.append(list)}content.before(layout);main.append(content);const footer=document.createElement('div');footer.className='pc-window-status';const left=document.createElement('span');left.textContent=status||t('工作記錄','Work records');const right=document.createElement('span');right.textContent=t('本機檔案','Local files');footer.append(left,right);layout.append(toolbar,main,footer);pcBindPreview(back||pcRoot)}
function pcHeader(title,meta){const header=document.createElement('header');header.className='pc-document-header';const heading=document.createElement('h3');heading.textContent=title;const info=document.createElement('div');info.className='pc-document-meta';info.textContent=meta;header.append(heading,info);$('content').prepend(header)}
const originalComputerMail=mail,originalComputerTrash=trash,originalComputerFiles=files,originalStudioFiles=c2files,originalComputerChat=workChat,originalStudioMessages=c2messages;
function pcFileType(label){return /Recordings|影片/.test(label)?'folder':/png|photo|照片/.test(label)?'photo':'document'}
function pcLegacyBrowser(type,renderLegacy,index=-1,studio=false){setMode('pc-ui');renderLegacy();pcUnmount();const content=$('content');content.querySelectorAll('.app-nav').forEach(e=>e.remove());const actions=Array.from(content.children).filter(e=>e.tagName==='BUTTON'&&!/^[←⌂]/.test(e.textContent.trim()));const labels=actions.map(e=>e.textContent);const reload=i=>pcLegacyBrowser(type,renderLegacy,i,studio);const rows=labels.map(label=>({label,icon:type==='mail'?'mail':pcFileType(label),detail:type==='trash'?t('已刪除的項目','Deleted item'):type==='mail'?t('收件匣 · CREW','Inbox · CREW'):/txt/.test(label)?t('文字文件','Text document'):t('工作記錄','Work record')}));content.replaceChildren();if(index>=0&&actions[index]){actions[index].onclick();pcHeader(labels[index],type==='mail'?t('收件人：CREW · 內部郵件','To: CREW · Internal mail'):type==='trash'?t('垃圾桶中的檔案 · 預覽','Trash item · Preview'):t('工作站 / ','Workstation / ')+(studio?'Rehearsal':'Backstage'));}else{const heading=document.createElement('p');heading.className='pc-empty-heading';heading.textContent=type==='trash'?t('垃圾桶','Trash'):studio?t('排練檔案','Rehearsal files'):t('後台檔案','Backstage files');const description=document.createElement('p');description.className='pc-folder-description';description.textContent=type==='trash'?t('已刪除的項目仍可打開查看。','Deleted items can still be opened and inspected.'):t('打開文件，核對內容與相關記錄。','Open a file to compare its contents with other records.');const grid=document.createElement('div');grid.className='pc-file-grid';rows.forEach((row,i)=>{const button=document.createElement('button');button.className='pc-file-tile';button.type='button';const label=document.createElement('span');label.textContent=row.label;const detail=document.createElement('small');detail.textContent=row.detail;button.append(pcGlyph(row.icon),label,detail);button.onclick=()=>reload(i);grid.append(button)});content.append(heading,description,grid)}pcFrame(type,type==='mail'?t('郵件 · 收件匣','Mail · Inbox'):type==='trash'?t('垃圾桶','Trash'):studio?t('排練檔案','Rehearsal files'):t('後台檔案','Backstage files'),{rows:index>=0?rows:[],selected:index,onSelect:reload,back:index>=0?()=>reload(-1):null,status:rows.length+t(' 個項目',' items')})}
mail=function(){pcLegacyBrowser('mail',originalComputerMail,0)};trash=function(){pcLegacyBrowser('trash',originalComputerTrash)};files=function(){pcLegacyBrowser('files',originalComputerFiles)};c2files=function(){pcLegacyBrowser('files',originalStudioFiles,-1,true)};
openApp=function(a,b,fn){setMode('pc-ui');fn();if(!document.getElementById('pc-app-layout'))pcFrame('document',t(a,b),{back:activeChapter===2?c2desk:desk})};
function pcChatFrame(studio){if(studio)originalStudioMessages();else originalComputerChat();pcUnmount();const content=$('content');content.querySelectorAll('.app-nav').forEach(e=>e.remove());Array.from(content.children).forEach(element=>{if(element.tagName==='BUTTON'&&/^[←⌂]/.test(element.textContent.trim())){element.remove();return}if(element.classList.contains('chat-bubble')){element.dataset.initial=element.querySelector('small')?.textContent[0]||'C';return}if(element.tagName==='P'){const text=element.textContent,match=text.match(/^([A-Za-z]+)\s*·/);const name=match?match[1]:'CREW';const bubbleElement=document.createElement('div');bubbleElement.className='chat-bubble';bubbleElement.dataset.initial=name[0];const sender=document.createElement('small');sender.textContent=name;const words=document.createElement('div');words.textContent=match?text.replace(/^([A-Za-z]+)\s*·\s*/,''):text;bubbleElement.append(sender,words);element.replaceWith(bubbleElement)}else if(element.tagName==='BUTTON'){element.classList.add(studio?'pc-save-record':'pc-attachment');if(!studio)element.prepend(pcGlyph('document'))}});const date=document.createElement('div');date.className='pc-chat-date';date.textContent=studio?t('10/11 · 排練群組','10/11 · Rehearsal crew'):t('演出工作群組','Show crew');content.prepend(date);const route=studio?c2messages:workChat;pcFrame('chat','Work Chat',{rows:[{label:studio?t('排練群組','Rehearsal crew'):t('演出工作群組','Show crew'),icon:'chat',detail:studio?'Jamie · Alex':'Jamie'}],selected:0,onSelect:route,status:t('工作訊息記錄','Work message archive')})}
workChat=function(){pcChatFrame(false)};c2messages=function(){pcChatFrame(true)};


// Release fixes: keep hit areas separate and bind the current device renderers.
const releaseLabels={desk:['工作電腦','Work laptop'],case:['吉他盒','Guitar case'],coat:['外套口袋','Jacket pocket'],bag:['用品袋','Gear bag'],door:['後台門','Backstage door'],morton:['Morton','Morton'],sheet:['整理樂譜','Sheet music']};
const releaseRender=render;
render=function(){releaseRender();document.querySelectorAll('[data-obj]').forEach(e=>e.setAttribute('aria-label',t(...releaseLabels[e.dataset.obj])));sheetButton.setAttribute('aria-label',t('整理樂譜','Arrange sheet music'));document.querySelectorAll('[data-c2]').forEach(e=>{const names={desk:['工作站','Workstation'],guitar:['吉他架','Guitar stand'],amp:['音箱','Amp'],metro:['節拍器','Metronome'],pedals:['踏板板','Pedalboard'],bag:['器材袋','Equipment bag'],box:['鑰匙盒','Key box'],door:['練習室門','Studio door'],morton:['Morton','Morton'],drums:['架子鼓','Drum kit'],mic:['麥克風','Microphone']};e.setAttribute('aria-label',t(...names[e.dataset.c2]))});if(manualSave)manualSave.textContent=t('存檔','Save');if(exploreNav){exploreNav.hidden=activeChapter!==1;exploreNav.querySelectorAll('button').forEach(e=>e.textContent=t(...releaseLabels[e.dataset.target]))}};
let manualSave=null,exploreNav=null;
manualSave=btn('存檔','Save',()=>{save();$('save-status').textContent=t('✓ 進度已儲存','✓ Progress saved');setTimeout(()=>{$('save-status').textContent=''},3000)});manualSave.id='manual-save';document.querySelector('header').append(manualSave);
const saveStatus=document.createElement('span');saveStatus.id='save-status';saveStatus.setAttribute('role','status');document.querySelector('footer').prepend(saveStatus);
exploreNav=document.createElement('nav');exploreNav.className='explore-nav';exploreNav.setAttribute('aria-label','Backstage objects');document.querySelector('main').prepend(exploreNav);
for(const id of ['desk','sheet','case','coat','bag','door','morton']){const b=btn(...releaseLabels[id],()=>id==='sheet'?sheetButton.click():document.querySelector('[data-obj="'+id+'"]').click());b.dataset.target=id;exploreNav.append(b)}
document.querySelector('[data-obj="desk"]').onclick=()=>desk();document.querySelector('[data-c2="desk"]').onclick=()=>c2desk();
// Preserve the source image proportions; avoid stretching the character or painting over nearby props.
mortonSprite.style.objectFit='contain';
$('close').setAttribute('aria-label','Close');
render();openMenu();

// The recovered pickup card becomes the item in hand; the first scan remains historical evidence.
const cardBeforeRecovery=c4card,terminalBeforeRecovery=c4terminal;
c4card=function(){if(!E().restored){cardBeforeRecovery();return}c4show('card','已領回的相片卡','Recovered pickup card');const paper=document.createElement('div');paper.className='c4-ticket';paper.textContent='B42 ◢';$('content').append(paper);p('目前持有：B42，三角缺角。已由 Maya 核對並交還。','In hand: B42, triangular corner notch. Verified and returned by Maya.');c4clue('recovered');action('查看先前 B43 的記錄','Review earlier B43 evidence',()=>{c4show('back','先前的錯誤卡片','Earlier incorrect card');c4clue('wrong')})};
c4terminal=function(){if(!E().restored){terminalBeforeRecovery();return}c4show('terminal','STAR COMMAND · PHOTO','STAR COMMAND · PHOTO','pc-ui');p('目前卡片：B42。已核對 42 號車；原始分數與相片已領回。','Current card: B42. Vehicle 42 verified; original scores and photo recovered.');action('開啟 B42 相片','Open photo B42',()=>{c4show('recovered','B42 · MISSION PHOTO','B42 · MISSION PHOTO','pc-ui');c4photo(true);c4clue('recovered')});action('查看先前掃描的 B43','Review earlier B43 scan',()=>{c4show('badphoto','B43 · PREVIOUS SCAN','B43 · PREVIOUS SCAN','pc-ui');c4photo(false);c4clue('badphoto')});action('查看原始車次紀錄','View original vehicle archive',()=>{c4show('archived','VEHICLE ARCHIVE','VEHICLE ARCHIVE','pc-ui');c4clue('archived')});action('還原換卡經過','Reconstruct the card swap',c4solve)};
// Keep scene and toolbar entry points current after device functions are refined.
const renderRecovery=c4render;c4render=function(){renderRecovery();if(activeChapter===4){const buttons=c4nav.querySelectorAll('button');if(buttons[0])buttons[0].onclick=()=>c4card();if(buttons[1])buttons[1].onclick=()=>c4terminal();c4room.querySelectorAll('button').forEach(b=>{if(b.getAttribute('aria-label')===t('取相片電腦','Photo terminal'))b.onclick=()=>c4terminal()})}};
// Explicit labels keep reconstruction controls usable on small screens and with assistive tools.
const showAccessible=show;show=function(a,b){showAccessible(a,b);$('modal').setAttribute('aria-label',t(a,b));};
render();openMenu();
